/**
 * AI copilot proposal schemas (docs/12-ai-copilot.md).
 *
 * The AI's ONLY write path is a *proposal*: a typed object the model produces
 * via a tool call, schema-validated server-side, rendered as a card in the
 * parent app, and executed by the app THROUGH THE SAME MUTATIONS the manual
 * editors use — only after an explicit confirmation tap. One zod source of
 * truth from tool definition → proposal card → executed write.
 */
import { z } from 'zod'

import { SYSTEM_APP_NAMES, SYSTEM_COMMANDS } from './protocol'
import { quietHoursSchema } from './schemas'

// ---- Policy diff proposal ---------------------------------------------------
// A proposal is a small list of operations against one kid's policy. Each op
// maps 1:1 onto an existing parent-app mutation; `summary` is the model's
// plain-English description shown on the card ("Games: 30 min on school
// days, 60 min on weekends").

export const budgetUpsertOpSchema = z.object({
  op: z.literal('upsert_budget'),
  /** Matched case-insensitively against existing budget names; no match = create. */
  name: z.string().min(1).max(40),
  seconds_per_day: z.record(z.string(), z.number().int().min(0).max(86400)),
  system_apps: z.array(z.enum(SYSTEM_APP_NAMES)).default([]),
  /** Catalog slugs — the app resolves slugs → library_app_ids at execute time. */
  library_app_slugs: z.array(z.string()).default([]),
})

export const budgetDeleteOpSchema = z.object({
  op: z.literal('delete_budget'),
  name: z.string().min(1).max(40),
})

export const quietHoursOpSchema = z.object({
  op: z.literal('set_quiet_hours'),
  rules: quietHoursSchema,
})

export const systemAppOpSchema = z.object({
  op: z.literal('set_system_app'),
  name: z.enum(SYSTEM_APP_NAMES),
  enabled: z.boolean(),
})

export const libraryAppOpSchema = z.object({
  op: z.literal('set_library_app'),
  slug: z.string().min(1),
  enabled: z.boolean(),
})

export const setAudioOpSchema = z
  .object({
    op: z.literal('set_audio'),
    /** Cap on the device's effective app volume; omit to leave unchanged. */
    max_volume_pct: z.number().int().min(10).max(100).optional(),
    /** false silences library-app audio; system sounds keep working. */
    game_sounds: z.boolean().optional(),
  })
  .refine((op) => op.max_volume_pct !== undefined || op.game_sounds !== undefined, {
    message: 'set_audio needs max_volume_pct and/or game_sounds',
  })

export const grantTimeOpSchema = z.object({
  op: z.literal('grant_time'),
  budget_name: z.string().min(1).max(40),
  extra_seconds: z
    .number()
    .int()
    .min(60)
    .max(4 * 3600),
})

export const policyOpSchema = z.discriminatedUnion('op', [
  budgetUpsertOpSchema,
  budgetDeleteOpSchema,
  quietHoursOpSchema,
  systemAppOpSchema,
  libraryAppOpSchema,
  setAudioOpSchema,
  grantTimeOpSchema,
])
export type PolicyOp = z.infer<typeof policyOpSchema>

export const policyDiffProposalSchema = z.object({
  kind: z.literal('policy_diff'),
  kid_id: z.guid(),
  summary: z.string().min(1).max(500),
  ops: z.array(policyOpSchema).min(1).max(10),
})
export type PolicyDiffProposal = z.infer<typeof policyDiffProposalSchema>

// ---- Command proposal -------------------------------------------------------
// Executed on confirm via POST /api/commands (the audited path).

export const commandProposalSchema = z.object({
  kind: z.literal('command'),
  device_id: z.guid(),
  app_ref: z.string().min(1),
  name: z.union([z.enum(SYSTEM_COMMANDS), z.string().min(1)]),
  args: z.record(z.string(), z.unknown()).default({}),
  summary: z.string().min(1).max(300),
})
export type CommandProposal = z.infer<typeof commandProposalSchema>

export const aiProposalSchema = z.discriminatedUnion('kind', [
  policyDiffProposalSchema,
  commandProposalSchema,
])
export type AiProposal = z.infer<typeof aiProposalSchema>

// ---- Model configuration (the Isla env pattern) -----------------------------
export const OPENAI_MODEL_DEFAULT = 'gpt-5'
export const OPENAI_MINI_MODEL_DEFAULT = 'gpt-5-mini'
