import { z } from 'zod'
import {
  AUDIO_MUTE_MAX_S,
  BUTTONS,
  COMMAND_STATUSES,
  DEVICE_STATUSES,
  DOC_SYNC_MODES,
  OUTBOX_OPS,
  PAIRING_CODE_LENGTH,
  REWARD_MODES,
  SYSTEM_APP_NAMES,
} from './protocol'

// NOTE: ids use z.guid() (any 8-4-4-4-12 hex), not z.uuid() — zod v4's uuid()
// enforces RFC-4122 version/variant nibbles, which rejects hand-written ids
// like the seed's 3333…; Postgres's uuid type is the real authority.

// app_ref: 'system' | 'system:{name}' | 'lib:{slug}'
export const appRefSchema = z
  .string()
  .regex(/^(system|system:[a-z_]+|lib:[a-z0-9][a-z0-9-]*)$/, 'invalid app_ref')

export const pairingCodeSchema = z.string().regex(new RegExp(`^\\d{${PAIRING_CODE_LENGTH}}$`))

// ---- Device registration / pairing / token ---------------------------------

export const registerRequestSchema = z.object({
  fingerprint: z.string().length(64), // sha256 hex of pubkey
  pubkey: z.string(), // PEM or base64 DER, ECDSA P-256
  hw_model: z.string(),
  fw_version: z.string(),
})

export const registerResponseSchema = z.object({
  pairing_code: pairingCodeSchema,
  expires_at: z.iso.datetime(),
})

export const claimRequestSchema = z.object({
  code: pairingCodeSchema,
  kid_id: z.guid(),
  name: z.string().min(1).max(60),
})

// Two-step signed challenge: bare call → nonce; signed call → JWT.
export const tokenChallengeResponseSchema = z.object({
  nonce: z.string(),
  expires_at: z.iso.datetime(),
})

export const tokenRequestSchema = z.object({
  fingerprint: z.string().length(64),
  // Self-certifying: server checks sha256(pubkey) === fingerprint, then verifies
  // the signature with this pubkey — no server-side pubkey storage needed.
  pubkey: z.string(),
  nonce: z.string(),
  signature: z.string(), // base64 ECDSA P-256 signature over `${fingerprint}.${nonce}`
})

export const tokenResponseSchema = z.object({
  token: z.string(),
  expires_at: z.iso.datetime(),
  device_id: z.guid(),
  family_id: z.guid(),
})

// ---- Documents -------------------------------------------------------------

export const docPutSchema = z.object({
  op: z.literal('doc.put'),
  app_ref: appRefSchema,
  doc_type: z.string(),
  doc_key: z.string(),
  payload: z.record(z.string(), z.unknown()).default({}),
  assets: z.record(z.string(), z.string()).optional(), // {name: local filename → storage path}
})

export const docStatusSchema = z.object({
  op: z.literal('doc.status'),
  doc_id: z.guid(),
  status: z.string(),
})

export const voiceMessagePayloadSchema = z.object({
  duration_ms: z.number().int().positive(),
  codec: z.string(), // AUDIO_CODEC for device-recorded
})

// ---- Events / usage / status / time ----------------------------------------

export const eventEmitSchema = z.object({
  op: z.literal('event.emit'),
  app_ref: appRefSchema,
  name: z.string(),
  payload: z.record(z.string(), z.unknown()).default({}),
  occurred_at: z.iso.datetime().optional(),
})

export const statusReportSchema = z.object({
  op: z.literal('status.report'),
  battery: z.number().int().min(0).max(100),
  fw: z.string(),
})

export const usageReportSchema = z.object({
  op: z.literal('usage.report'),
  date: z.iso.date(),
  usage: z.record(appRefSchema, z.number().int().nonnegative()), // seconds per app_ref
})

export const timeRequestSchema = z.object({
  op: z.literal('time.request'),
  budget_id: z.guid(),
  app_ref: appRefSchema,
})

export const commandResultSchema = z.object({
  op: z.literal('command.result'),
  command_id: z.guid(),
  status: z.enum(['acked', 'failed']),
  result: z.record(z.string(), z.unknown()).optional(),
})

export const outboxJobSchema = z.discriminatedUnion('op', [
  docPutSchema,
  docStatusSchema,
  eventEmitSchema,
  statusReportSchema,
  usageReportSchema,
  timeRequestSchema,
  commandResultSchema,
])
export type OutboxJob = z.infer<typeof outboxJobSchema>

// ---- Commands (parent → device) --------------------------------------------

export const commandCreateSchema = z.object({
  device_id: z.guid(),
  app_ref: appRefSchema,
  name: z.string(),
  args: z.record(z.string(), z.unknown()).default({}),
  expires_in_s: z.number().int().positive().max(3600).default(300),
})

export const inputInjectArgsSchema = z.object({
  button: z.enum(BUTTONS),
  action: z.enum(['press', 'release', 'tap']),
})

export const screenFollowArgsSchema = z.object({
  seconds: z.number().int().positive().max(120),
})

// audio.mute: temporary remote shush; seconds: 0 lifts an active mute early.
export const audioMuteArgsSchema = z.object({
  seconds: z.number().int().min(0).max(AUDIO_MUTE_MAX_S),
})

// ---- Policy document (what the device syncs & enforces) --------------------

// kid_policies.audio jsonb: both keys optional — absent max_volume_pct means
// no cap; absent game_sounds means true (library-app tones+sfx allowed).
// System sounds (message chirp, ring) are never governed by game_sounds.
export const kidPolicyAudioSchema = z.object({
  max_volume_pct: z.number().int().min(10).max(100).optional(),
  game_sounds: z.boolean().optional(),
})
export type KidPolicyAudio = z.infer<typeof kidPolicyAudioSchema>

// kid_policies.location (docs/13-location.md). Absent enabled = false — the
// whereabouts feature fails closed at every layer.
export const kidPolicyLocationSchema = z.object({
  enabled: z.boolean().optional(),
  notify_arrive: z.boolean().optional(),
  notify_depart: z.boolean().optional(),
  // LTE SKU only (docs/14-cellular.md): GNSS fixes off WiFi. Absent = false —
  // precise location is a separate, stricter consent than semantic places.
  precise: z.boolean().optional(),
})
export type KidPolicyLocation = z.infer<typeof kidPolicyLocationSchema>

export const quietHoursSchema = z.array(
  z.object({
    // ISO weekday numbers, 1=Mon .. 7=Sun — what the mobile editor writes
    // and the firmware's quiet-hours scheduler parses.
    days: z.array(z.number().int().min(1).max(7)),
    start: z.string().regex(/^\d{2}:\d{2}$/),
    end: z.string().regex(/^\d{2}:\d{2}$/),
  }),
)

export const timeBudgetSchema = z.object({
  id: z.guid(),
  name: z.string(),
  seconds_per_day: z.record(z.string(), z.number().int().nonnegative()), // {"default":3600,"sat":7200}
  system_apps: z.array(z.enum(SYSTEM_APP_NAMES)),
  library_app_slugs: z.array(z.string()), // resolved from library_app_ids for the device
})

export const budgetGrantSchema = z.object({
  budget_id: z.guid(),
  extra_seconds: z.number().int(),
  effective_date: z.iso.date(),
})

export const policyDocSchema = z.object({
  hash: z.string(), // device compares to last-seen
  system_apps: z.record(z.enum(SYSTEM_APP_NAMES), z.boolean()),
  quiet_hours: quietHoursSchema,
  library_app_slugs: z.array(z.string()), // enabled apps
  timezone: z.string(),
  time_budgets: z.array(timeBudgetSchema),
  grants_today: z.array(budgetGrantSchema),
})
export type PolicyDoc = z.infer<typeof policyDocSchema>

// ---- Rewards (docs/16-rewards.md) ------------------------------------------

// reward_action: the kid's choice, a device-origin document from lib:rewards.
// `seq` is a per-device client counter the server echoes back in the next
// reward_state (`aseq`) so the app knows its optimistic UI is confirmed.
export const rewardActionSchema = z.discriminatedUnion('action', [
  z.object({
    action: z.literal('pick'), // spend 1 pick on a regular sticker
    sticker: z.string().min(1).max(32),
    seq: z.number().int().min(1),
  }),
  z.object({
    action: z.literal('wait'), // start ripening a pick (the patience mechanic)
    pick: z.string().min(4).max(36), // sticker_picks id (or its short prefix)
    seq: z.number().int().min(1),
  }),
  z.object({
    action: z.literal('combine'), // mint a super sticker from its recipe
    target: z.string().min(1).max(32),
    seq: z.number().int().min(1),
  }),
])
export type RewardAction = z.infer<typeof rewardActionSchema>

// reward_state: the server-composed view pushed to the kid's devices as a
// versioned document. Short keys on purpose — the device doc payload cap is
// 1536 bytes (docstore VUPP_DOC_PAYLOAD_CAP).
export const rewardStatePickSchema = z.object({
  i: z.string(), // sticker_picks id prefix (8 chars)
  n: z.number().int().min(1), // picks in this credit
  s: z.enum(['a', 'w']), // available | waiting
  wu: z.number().int().optional(), // epoch s, while waiting
  x: z.number().int().optional(), // wait multiplier
})

export const rewardStateSchema = z.object({
  v: z.literal(1),
  m: z.enum(REWARD_MODES),
  c: z.number().int(), // coin balance
  wh: z.number().int(), // wait_hours
  wx: z.number().int(), // wait_multiplier
  now: z.number().int(), // server epoch s at compose time
  aseq: z.number().int().optional(), // highest processed action seq (this device)
  pk: z.array(rewardStatePickSchema),
  st: z.record(z.string(), z.number().int().nonnegative()), // owned {slug: count}
})
export type RewardState = z.infer<typeof rewardStateSchema>

// ---- OTA -------------------------------------------------------------------

export const otaManifestSchema = z.object({
  version: z.string(),
  url: z.url(),
  sha256: z.string().length(64),
  min_battery: z.number().int().min(0).max(100),
})

// ---- Misc row-shaped helpers -----------------------------------------------

export const deviceStatusSchema = z.enum(DEVICE_STATUSES)
export const commandStatusSchema = z.enum(COMMAND_STATUSES)
export const docSyncModeSchema = z.enum(DOC_SYNC_MODES)
export const outboxOpSchema = z.enum(OUTBOX_OPS)
