import { APP_ENGINE_VERSION } from '@vupp/shared'

import { type Ctx, emit, progress } from '../output.js'
import { resolveSimAssets, SimAssetError } from '../sim/assets.js'
import { BrowserError, ensureBrowser } from '../sim/browser.js'

/**
 * Get everything in place, on purpose, before it is needed.
 *
 * Both of the heavy things this CLI depends on — the simulator assets and a
 * browser to run them in — are downloads. Doing either lazily in the middle of
 * `vupp run` means someone's first build stalls for a minute with no
 * explanation, which reads as a hang and is the most likely moment for a
 * non-technical person to give up. So there is a command whose whole job is to
 * do the downloading, say what it is doing, and be run first.
 *
 * It is also the honest place to report that no simulator is configured, since
 * that is a real state: studio-sim is currently deployed through Cloudflare's
 * temporary-accounts flow, so there is no permanent URL to compile in.
 */
export async function cmdDoctor(ctx: Ctx, opts: { refresh?: boolean } = {}): Promise<number> {
  const report: Record<string, unknown> = { engine: APP_ENGINE_VERSION }
  let ok = true

  try {
    const assets = await resolveSimAssets({
      refresh: opts.refresh,
      onProgress: (m) => progress(ctx, m),
    })
    report.sim = {
      ok: true,
      dir: assets.dir,
      source: assets.source,
      engine: assets.manifest?.engine ?? null,
    }
    if (assets.manifest && assets.manifest.engine !== APP_ENGINE_VERSION) {
      report.sim = {
        ...(report.sim as object),
        warning:
          `the simulator was built from engine ${assets.manifest.engine} but this CLI knows engine ` +
          `${APP_ENGINE_VERSION}. Apps may lint clean here and be refused there.`,
      }
    }
  } catch (err) {
    ok = false
    report.sim = { ok: false, error: err instanceof SimAssetError ? err.message : String(err) }
  }

  try {
    const chrome = await ensureBrowser((m) => progress(ctx, m))
    report.browser = { ok: true, path: chrome.executablePath, source: chrome.source }
  } catch (err) {
    ok = false
    report.browser = { ok: false, error: err instanceof BrowserError ? err.message : String(err) }
  }

  emit(ctx, { ok, ...report }, () => {
    const lines: string[] = []
    const sim = report.sim as {
      ok: boolean
      dir?: string
      source?: string
      error?: string
      warning?: string
    }
    const browser = report.browser as {
      ok: boolean
      path?: string
      source?: string
      error?: string
    }

    lines.push(
      sim.ok
        ? `simulator  ok    ${sim.dir} (${sim.source})`
        : `simulator  FAIL\n${indent(sim.error)}`,
    )
    if (sim.warning) lines.push(`           warn  ${sim.warning}`)
    lines.push(
      browser.ok
        ? `browser    ok    ${browser.path} (${browser.source})`
        : `browser    FAIL\n${indent(browser.error)}`,
    )
    lines.push(`engine     ${APP_ENGINE_VERSION}`)
    if (ok) lines.push('', 'Ready. Try: vupp init my-game && cd my-game && vupp run')
    return lines.join('\n')
  })

  return ok ? 0 : 1
}

function indent(text?: string): string {
  return (text ?? 'unknown')
    .split('\n')
    .map((l) => `           ${l}`)
    .join('\n')
}
