import { writeFile } from 'node:fs/promises'
import { resolve } from 'node:path'

import { writeAppZip } from '@vupp/app-package'

import { type Ctx, emit } from '../output.js'
import { lint, lintFailure, readProject, titleOf } from '../project.js'

/**
 * The handoff.
 *
 * A zip, produced by exactly the writer the parent app reads with
 * (@vupp/app-package): app.json, main.lua, lib/*.lua and a studio.json sidecar
 * saying who made it. It goes through Messages or Mail or AirDrop like any
 * other file, and the parent opens it in the Vupp app, plays it, and decides
 * whether it goes on their child's device.
 *
 * That last step is the point, and it is why this CLI stops here rather than
 * publishing. Anyone in a family may BUILD an app — a sibling, a grandparent, a
 * therapist, and now anyone with an AI and this tool. Putting one on a child's
 * device is a parent's call, and /api/apps/publish enforces that with
 * role === 'parent'. A CLI that published directly would route around the one
 * gate the whole design rests on.
 *
 * It refuses to package an app that does not lint, for the same reason the
 * publish screen does: an app that cannot pass on the way out was never going
 * to install.
 */
export interface PackageOptions {
  out?: string
  author?: string
  note?: string
}

export async function cmdPackage(ctx: Ctx, dir: string, opts: PackageOptions): Promise<number> {
  const files = await readProject(dir)

  const checked = lint(files)
  if (!checked.ok) {
    emit(ctx, { ok: false, where: 'check', error: lintFailure(checked) }, () =>
      lintFailure(checked),
    )
    return 1
  }

  const title = titleOf(files)
  const bytes = writeAppZip(files, {
    kind: 'vupp-studio-app',
    version: 1,
    title,
    author: opts.author,
    note: opts.note,
  })

  const out = resolve(opts.out ?? `${safeName(title)}.zip`)
  await writeFile(out, bytes)

  emit(
    ctx,
    {
      ok: true,
      path: out,
      title,
      bytes: bytes.length,
      files: Object.keys(files).sort(),
      play_url: PLAY_URL,
      // The zip is not the end of the job. Somebody still has to find out
      // whether a child enjoys it, and that cannot be checked from here — so
      // the result says how, in the words to hand over.
      next:
        `Tell them the game is ready, and OFFER to let them play it now. The fastest route ` +
        `is \`vupp play ${out}\` — it opens a browser with the game already running, no file ` +
        `picker involved. To send it to somebody else, give them ${out} plus ${PLAY_URL}, ` +
        `where they drop the file in and play with nothing installed. Then ask what they ` +
        `want changed, and iterate.`,
    },
    () =>
      [
        `Wrote ${out} (${Math.round(bytes.length / 102.4) / 10} KB)`,
        '',
        `Play it now:      vupp play ${out}`,
        `Send it to them:  ${out} plus ${PLAY_URL}`,
        '                  (they drop the file in — nothing to install)',
        '',
        'To put it on a device: open the zip in the Vupp app and publish from there.',
        'Publishing is a parent-only step by design.',
      ].join('\n'),
  )
  return 0
}

/** The hosted player. Anyone can open it; the zip never leaves their machine. */
const PLAY_URL = 'https://nicholasareed.github.io/vupp-sdk/play/'

function safeName(title: string): string {
  return title.replace(/[^A-Za-z0-9 _-]/g, '').trim() || 'vupp-app'
}
