import { existsSync } from 'node:fs'
import { resolve } from 'node:path'

import { REFERENCE_SLUGS, readReferenceApp, SKELETON } from '@vupp/app-reference'
import { APP_ENGINE_VERSION, STUDIO_DRAFT_SLUG } from '@vupp/shared'

import { type Ctx, emit } from '../output.js'
import { ProjectError, type ProjectFiles, writeProject } from '../project.js'

/**
 * Start an app.
 *
 * Two flavours, and the difference matters more than it looks. The bare
 * skeleton is the smallest thing that runs and moves. `--from <slug>` copies a
 * reference app that already ships on the hardware, with its slug rewritten to
 * "draft" — which is the faster start when the thing being asked for resembles
 * something in the library, and is much better than an AI reconstructing a maze
 * from memory.
 */
export interface InitOptions {
  from?: string
  title?: string
  force?: boolean
}

export async function cmdInit(ctx: Ctx, dir: string, opts: InitOptions): Promise<number> {
  const root = resolve(dir)
  if (!opts.force && existsSync(resolve(root, 'main.lua'))) {
    throw new ProjectError(`${root} already holds an app. Pass --force to overwrite it.`)
  }

  const files = opts.from ? fromReference(opts.from, opts.title) : skeleton(opts.title)
  await writeProject(root, files)

  emit(
    ctx,
    { ok: true, dir: root, files: Object.keys(files).sort(), from: opts.from ?? null },
    () =>
      [
        `Created ${root}`,
        ...Object.keys(files)
          .sort()
          .map((f) => `  ${f}`),
        '',
        'Next: vupp run   (then vupp playtest)',
      ].join('\n'),
  )
  return 0
}

function skeleton(title?: string): ProjectFiles {
  // The same skeleton the studio agent is given, so the two front doors start
  // from identical code (@vupp/app-reference).
  const main = SKELETON.split('\n')
    .filter((line) => !line.startsWith('#') && line.trim() !== '')
    .map((line) => line.replace(/^ {4}/, ''))
    .join('\n')
  return {
    'app.json': manifest(title ?? 'My Game'),
    'main.lua': `${main}\n`,
  }
}

function fromReference(slug: string, title?: string): ProjectFiles {
  const app = readReferenceApp(slug)
  if (!app.ok || !('files' in app)) {
    throw new ProjectError(`No reference app "${slug}". Available: ${REFERENCE_SLUGS.join(', ')}`)
  }
  const files: ProjectFiles = { ...app.files }
  // The preview device installs under "draft"; a copy that kept its original
  // slug would be refused by the same lint the studio uses.
  const parsed = JSON.parse(files['app.json'] ?? '{}') as Record<string, unknown>
  parsed.slug = STUDIO_DRAFT_SLUG
  parsed.title = title ?? `${String(parsed.title ?? 'Copy')} (copy)`
  parsed.version = '1.0.0'
  files['app.json'] = `${JSON.stringify(parsed, null, 2)}\n`
  return files
}

function manifest(title: string): string {
  return `${JSON.stringify(
    {
      slug: STUDIO_DRAFT_SLUG,
      title,
      version: '1.0.0',
      author: 'A Vupp family',
      category: 'game',
      fps: 30,
      capabilities: [],
      min_engine: APP_ENGINE_VERSION,
      parent: { version: 1, documents: {}, commands: {}, events: {} },
    },
    null,
    2,
  )}\n`
}
