import { existsSync } from 'node:fs'
import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises'
import { dirname, join, relative, resolve, sep } from 'node:path'

import {
  APP_ENGINE_VERSION,
  formatLintProblems,
  type LintResult,
  lintProject,
  STUDIO_DRAFT_SLUG,
  STUDIO_FILE_PATH_RE,
} from '@vupp/shared'

/**
 * A Vupp app on disk.
 *
 * The same three-shape layout as app-library/<slug>/ and as the zip the parent
 * app imports: app.json, main.lua, lib/*.lua. Nothing else is part of the app,
 * so nothing else is read — a README or a .git next to it is simply not the
 * program, and silently packaging one would be the sort of surprise that turns
 * up later as a failed publish.
 */

export type ProjectFiles = Record<string, string>

export class ProjectError extends Error {}

/**
 * vupp-lint's view of a project written by an AI: no asset files (none of the
 * tooling can produce them yet), the engine at head, and the slug pinned to the
 * one the preview device installs under.
 *
 * Identical to apps/mobile/src/studio/lintOptions.ts on purpose. An app that
 * passed on its way into the simulator must not be refused on its way out.
 */
export const LINT_OPTIONS = {
  assets: false,
  engineVersion: APP_ENGINE_VERSION,
  requireSlug: STUDIO_DRAFT_SLUG,
}

export async function readProject(dir: string): Promise<ProjectFiles> {
  const root = resolve(dir)
  if (!existsSync(root)) throw new ProjectError(`${root} does not exist.`)

  const files: ProjectFiles = {}
  for (const path of await listSourcePaths(root)) {
    files[path] = await readFile(join(root, path), 'utf8')
  }

  if (!files['app.json'] || !files['main.lua']) {
    const missing = [!files['app.json'] && 'app.json', !files['main.lua'] && 'main.lua']
      .filter(Boolean)
      .join(' and ')
    throw new ProjectError(
      `${root} is not a Vupp app — ${missing} ${missing.includes('and') ? 'are' : 'is'} missing. ` +
        'Run `vupp init` to start one.',
    )
  }
  return files
}

async function listSourcePaths(root: string): Promise<string[]> {
  const found: string[] = []
  for (const name of ['app.json', 'main.lua']) {
    if (existsSync(join(root, name))) found.push(name)
  }
  const libDir = join(root, 'lib')
  if (existsSync(libDir)) {
    for (const entry of await readdir(libDir, { withFileTypes: true })) {
      if (!entry.isFile()) continue
      const rel = `lib/${entry.name}`
      if (STUDIO_FILE_PATH_RE.test(rel)) found.push(rel)
    }
  }
  return found.sort()
}

export async function writeProject(dir: string, files: ProjectFiles): Promise<void> {
  const root = resolve(dir)
  for (const [path, content] of Object.entries(files)) {
    if (!STUDIO_FILE_PATH_RE.test(path)) {
      throw new ProjectError(
        `"${path}" is not a path a Vupp app can have. Allowed: app.json, main.lua, lib/<name>.lua`,
      )
    }
    const target = join(root, path)
    if (relative(root, target).startsWith(`..${sep}`)) {
      throw new ProjectError(`"${path}" would write outside ${root}`)
    }
    await mkdir(dirname(target), { recursive: true })
    await writeFile(target, content)
  }
}

export function lint(files: ProjectFiles): LintResult {
  return lintProject(files, LINT_OPTIONS)
}

/** The lint failure, formatted the way the studio agent already reads it. */
export function lintFailure(result: LintResult): string {
  return `${formatLintProblems(result.errors)}\n\nNothing was written and the screen is unchanged.`
}

export function titleOf(files: ProjectFiles): string {
  try {
    const title = (JSON.parse(files['app.json'] ?? '{}') as { title?: unknown }).title
    return typeof title === 'string' && title.trim() ? title : 'Untitled'
  } catch {
    return 'Untitled'
  }
}
