/**
 * Two audiences, one command.
 *
 * A person running `vupp run` wants a sentence. An AI running `vupp run --json`
 * wants a value it can branch on without parsing prose. Both come out of the
 * same call so the two can never disagree about what happened — the JSON is the
 * result, and the human text is a rendering of it.
 *
 * Everything an AI needs goes to stdout; progress and diagnostics go to stderr,
 * so `--json` output stays a single parseable document even while the sim is
 * narrating a browser download.
 */

export interface Ctx {
  json: boolean
  quiet: boolean
}

export function emit(ctx: Ctx, value: unknown, human: () => string): void {
  if (ctx.json) {
    process.stdout.write(`${JSON.stringify(value, null, 2)}\n`)
    return
  }
  const text = human()
  if (text) process.stdout.write(`${text}\n`)
}

export function progress(ctx: Ctx, message: string): void {
  if (!ctx.quiet && !process.env.VUPP_NO_PROGRESS) process.stderr.write(`  ${message}\n`)
}

export function warn(message: string): void {
  process.stderr.write(`${message}\n`)
}

/** Format a lint/run/playtest failure so a person sees the same thing the JSON says. */
export function fail(ctx: Ctx, value: Record<string, unknown>, human: () => string): never {
  if (ctx.json) process.stdout.write(`${JSON.stringify({ ok: false, ...value }, null, 2)}\n`)
  else process.stderr.write(`${human()}\n`)
  process.exit(1)
}
