// ---- Cellular / GNSS (docs/14-cellular.md) ---------------------------------
// The LTE SKU (SIM7670G Cat-1bis + GNSS) adds `location.fix` events: emitted
// only while off WiFi, at most every LOCATION_FIX_INTERVAL_S, and only when
// the fix moved beyond LOCATION_FIX_MIN_MOVE_M — change-only breadcrumbs,
// never continuous tracking. Gated on kid_policies.location.precise.
export const EVENT_LOCATION_FIX = 'location.fix'
export const LOCATION_FIX_INTERVAL_S = 180 // GNSS duty cycle while away from WiFi
export const LOCATION_FIX_MIN_MOVE_M = 75 // fixes that moved less are not emitted
export const LOCATION_SOURCES = ['wifi', 'gnss'] as const
