import { type PlaytestStep, padMask, STUDIO_MIN_PRESS_MS } from '@vupp/shared'
import type { Browser, Page } from 'puppeteer-core'

import { CHROME_ARGS, ensureBrowser } from './browser.js'
import { type AssetServer, serveAssets } from './serve.js'

/**
 * Driving apps-internal/studio-sim from Node.
 *
 * The page is used completely unmodified — same index.html, same bridge.js, same
 * WASM the parent app's WebView loads. bridge.js has exactly one React Native
 * assumption, and it is in `send()`:
 *
 *     const rn = window.ReactNativeWebView
 *     if (rn) rn.postMessage(JSON.stringify(msg))
 *     else console.log('[bridge]', msg)
 *
 * So we install that object before the page scripts run and the contract is
 * satisfied. Inbound is `window.__vuppBridge.receive(obj)`, which bridge.js
 * already documents as its primary path. Nothing here is a fork of the
 * simulator: a firmware change reaches the CLI by rebuilding the WASM, and a
 * bridge change reaches it for free.
 *
 * Timing constants are lifted from apps/mobile/src/studio/SimView.tsx rather
 * than re-derived. They were arrived at against real hardware and a real phone,
 * and a playtest that disagrees with the one in the app is worse than useless.
 */

/** How long after launch we keep listening before a crash stops being likely. */
const CRASH_GRACE_MS = 700
const WATCH_MS = 2000
const WATCH_EVERY_MS = 250
/** Backstop for a wedged VM (a boot that never finishes, say). */
const RUN_TIMEOUT_MS = 20_000
/** Generous: the caller controls the length, up to 24 steps of 3 s hold + 5 s wait. */
const PLAYTEST_TIMEOUT_MS = 120_000
/** The WASM runtime has a lot to do before it answers; a cold boot is 3-4 s. */
const BOOT_TIMEOUT_MS = 60_000

/**
 * Below this the canvas is one flat colour: nothing was drawn, or everything
 * was drawn off-canvas.
 */
const BLANK_DISTINCT = 2

export interface RunResult {
  ok: boolean
  error?: string
  where?: string
  warnings?: string[]
  title?: string
  fps?: number
}

export interface PlaytestFrame {
  i: number
  label?: string
  png_b64: string
}

export interface PlaytestResult {
  ok: boolean
  error?: string
  where?: string
  moves_on_its_own?: boolean
  steps?: {
    i: number
    label?: string
    buttons?: string[]
    distinct: number
    nonbg: number
    screen_changed: boolean
  }[]
  frames?: PlaytestFrame[]
}

type FromSim = { type: string; [key: string]: unknown }

export interface SimSessionOptions {
  assetsDir: string
  /** Every firmware stdout line, as it arrives. */
  onLog?: (line: string) => void
  onProgress?: (message: string) => void
}

export class SimSession {
  private constructor(
    private readonly browser: Browser,
    private readonly page: Page,
    private readonly server: AssetServer,
    private readonly opts: SimSessionOptions,
  ) {}

  private readonly logs: string[] = []
  private running: { title: string; fps: number } | null = null

  private pending: {
    resolve: (r: RunResult) => void
    graceTimer?: NodeJS.Timeout
    timeout: NodeJS.Timeout
  } | null = null

  private playing: { resolve: (r: PlaytestResult) => void; timeout: NodeJS.Timeout } | null = null

  static async start(opts: SimSessionOptions): Promise<SimSession> {
    const progress = opts.onProgress ?? (() => {})
    const server = await serveAssets(opts.assetsDir)
    const chrome = await ensureBrowser(progress)

    const puppeteer = await import('puppeteer-core')
    const browser = await puppeteer.launch({
      executablePath: chrome.executablePath,
      headless: true,
      args: CHROME_ARGS,
    })

    const page = await browser.newPage()
    await page.setViewport({ width: 320, height: 480 })

    const session = new SimSession(browser, page, server, opts)
    const booted = session.awaitBoot()

    // The RN shim, installed before any page script runs. `postMessage` is what
    // bridge.js reaches for; everything else about the page is untouched.
    await page.exposeFunction('__vuppFromSim', (raw: string) => session.onMessage(raw))
    await page.evaluateOnNewDocument(() => {
      // biome-ignore lint/suspicious/noExplicitAny: injected into the page realm
      ;(window as any).ReactNativeWebView = {
        postMessage: (raw: string) => {
          // biome-ignore lint/suspicious/noExplicitAny: injected into the page realm
          ;(window as any).__vuppFromSim(raw)
        },
      }
    })

    progress('booting the simulator')
    await page.goto(`${server.url}/index.html`, { waitUntil: 'domcontentloaded' })
    await booted
    progress('simulator ready')
    return session
  }

  /**
   * Resolve on `ready`, with the same ping fallback the app uses. The page
   * announces itself, so the polling normally does nothing — it is here because
   * a dropped `ready` leaves every later message queued forever with no symptom
   * beyond a sim that never answers.
   */
  private awaitBoot(): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const deadline = setTimeout(
        () => reject(new Error('the simulator never finished booting')),
        BOOT_TIMEOUT_MS,
      )
      const poll = setInterval(() => {
        void this.send({ type: 'ping' }).catch(() => {})
      }, 1000)
      this.onBooted = () => {
        clearTimeout(deadline)
        clearInterval(poll)
        resolve()
      }
    })
  }

  private onBooted: (() => void) | null = null

  private async send(msg: Record<string, unknown>): Promise<void> {
    // Double-encoded for the same reason apps/mobile/src/studio/bridge.ts does
    // it: raw Lua goes through here, and U+2028/U+2029 are legal in JSON but
    // are statement terminators to a JS parser.
    const literal = JSON.stringify(msg)
    await this.page.evaluate((payload: string) => {
      // biome-ignore lint/suspicious/noExplicitAny: injected into the page realm
      const bridge = (window as any).__vuppBridge
      if (bridge) bridge.receive(JSON.parse(payload))
    }, literal)
  }

  private onMessage(raw: string): void {
    let msg: FromSim
    try {
      msg = JSON.parse(raw) as FromSim
    } catch {
      return
    }

    switch (msg.type) {
      case 'ready':
        this.onBooted?.()
        this.onBooted = null
        break
      case 'pong':
        if (msg.booted) {
          this.onBooted?.()
          this.onBooted = null
        }
        break
      case 'log': {
        const line = String(msg.line ?? '')
        this.logs.push(line)
        this.opts.onLog?.(line)
        break
      }
      case 'running':
        this.running = { title: String(msg.title ?? ''), fps: Number(msg.fps ?? 0) }
        break
      case 'launched': {
        // It started, but a crash in update/draw needs a frame or two. Once the
        // crash window passes, look at what is actually on screen: "runs
        // without crashing" and "shows the child something" are different
        // questions and only the log stream answers the first.
        const p = this.pending
        if (p && !p.graceTimer) {
          p.graceTimer = setTimeout(() => {
            void this.send({
              type: 'watch_canvas',
              for_ms: WATCH_MS,
              every_ms: WATCH_EVERY_MS,
            }).catch(() => {})
          }, CRASH_GRACE_MS)
        }
        break
      }
      case 'canvas': {
        const distinct = Number(msg.distinct ?? 0)
        const changes = Number(msg.changes ?? 0)
        const samples = Number(msg.samples ?? 0)
        if (distinct < BLANK_DISTINCT) {
          this.settle({
            ok: false,
            where: 'blank',
            error:
              'The app runs without crashing but the screen is a single flat colour — ' +
              'nothing is being drawn, or everything is being drawn outside the ' +
              '160x240 canvas. Check the coordinates in vupp.draw.',
          })
          break
        }
        this.settle({
          ok: true,
          warnings:
            changes <= 1
              ? [
                  `Nothing on screen changed across ${samples} samples over ${WATCH_MS / 1000}s. ` +
                    'A still picture reads as broken to a small child — give it something ' +
                    'that moves on its own from the very first frame, before any input.',
                ]
              : undefined,
        })
        break
      }
      case 'shot': {
        const png = String(msg.png_b64 ?? '')
        const waiting = this.onShot
        this.onShot = null
        waiting?.(png)
        break
      }
      case 'play_result':
        this.settlePlay({
          ok: true,
          moves_on_its_own: Boolean(msg.moves_on_its_own),
          steps: msg.steps as PlaytestResult['steps'],
          frames: msg.frames as PlaytestFrame[],
        })
        break
      case 'crash': {
        const where = String(msg.where ?? 'crash')
        const error = String(msg.message ?? 'the app crashed')
        this.settle({ ok: false, error, where })
        // An app that dies mid-playtest is exactly what a playtest is for.
        this.settlePlay({ ok: false, error, where })
        break
      }
      case 'refused': {
        const error = String(msg.reason ?? 'the engine refused to start it')
        this.settle({ ok: false, error, where: 'load' })
        this.settlePlay({ ok: false, error, where: 'load' })
        break
      }
      case 'error': {
        const error = String(msg.message ?? 'the bridge failed')
        this.settle({ ok: false, error, where: 'bridge' })
        this.settlePlay({ ok: false, error, where: 'bridge' })
        break
      }
    }
  }

  private settle(result: RunResult): void {
    const p = this.pending
    if (!p) return
    this.pending = null
    if (p.graceTimer) clearTimeout(p.graceTimer)
    clearTimeout(p.timeout)
    p.resolve(
      this.running ? { ...result, title: this.running.title, fps: this.running.fps } : result,
    )
  }

  private settlePlay(result: PlaytestResult): void {
    const p = this.playing
    if (!p) return
    this.playing = null
    clearTimeout(p.timeout)
    p.resolve(result)
  }

  /** Write the project and launch it; resolves once it is running or has failed. */
  async writeAndRun(files: Record<string, string>): Promise<RunResult> {
    this.settle({ ok: false, error: 'superseded by a newer build' })
    this.running = null
    const result = new Promise<RunResult>((resolve) => {
      this.pending = {
        resolve,
        timeout: setTimeout(
          () => this.settle({ ok: false, error: 'the device never finished starting up' }),
          RUN_TIMEOUT_MS,
        ),
      }
    })
    await this.send({ type: 'write_and_run', files })
    return result
  }

  /**
   * Press buttons on the running app and capture what happens.
   *
   * Cold start first: vupp_apprt_start re-reads the app into a fresh lua_State,
   * so the scripted presses land on the screen a child would actually meet
   * rather than on whatever the previous playtest left up.
   */
  async playtest(steps: PlaytestStep[]): Promise<PlaytestResult> {
    this.settlePlay({ ok: false, error: 'superseded by a newer playtest' })
    const result = new Promise<PlaytestResult>((resolve) => {
      this.playing = {
        resolve,
        timeout: setTimeout(
          () => this.settlePlay({ ok: false, error: 'the playtest did not finish' }),
          PLAYTEST_TIMEOUT_MS,
        ),
      }
    })

    await this.send({ type: 'relaunch' })
    await delay(CRASH_GRACE_MS)
    // Names are resolved to the VUPP_PAD_* bitmask HERE, not in the page, so
    // the mask has exactly one definition (@vupp/shared) and the bridge stays a
    // dumb sensor — the same division the app keeps.
    await this.send({
      type: 'play',
      steps: steps.map((s) => ({
        mask: padMask(s.press),
        buttons: s.press,
        hold_ms: Math.max(STUDIO_MIN_PRESS_MS, s.hold_ms ?? STUDIO_MIN_PRESS_MS),
        wait_ms: s.wait_ms,
        shot: s.shot,
        label: s.label,
      })),
    })
    return result
  }

  /** One PNG of the 160x240 app canvas, base64, no data: prefix. */
  async shot(): Promise<string> {
    const shot = new Promise<string>((resolve, reject) => {
      const timeout = setTimeout(() => reject(new Error('the screenshot never arrived')), 10_000)
      this.onShot = (png) => {
        clearTimeout(timeout)
        resolve(png)
      }
    })
    await this.send({ type: 'shot' })
    return shot
  }

  private onShot: ((png: string) => void) | null = null

  /** Drop the draft's saved progress ("start fresh"). */
  async resetStore(): Promise<void> {
    await this.send({ type: 'reset_store' })
  }

  /** Everything the firmware printed, for a caller that wants the raw grammar. */
  log(): string[] {
    return [...this.logs]
  }

  async close(): Promise<void> {
    await this.browser.close().catch(() => {})
    await this.server.close().catch(() => {})
  }
}

function delay(ms: number): Promise<void> {
  return new Promise((ok) => setTimeout(ok, ms))
}
