/**
 * vupp-lint — a static check for Vupp app source, run before anything reaches
 * the VM (docs/17-studio.md).
 *
 * This is a QUALITY loop, not a safety gate. The Lua sandbox is the security
 * boundary and it is unchanged by anything here; the only job of this module is
 * to let the studio's model notice its own mistakes in milliseconds instead of
 * paying a full write-launch-crash round trip for each one.
 *
 * Every rule targets something a model trained on LOVE, PICO-8 and plain Lua
 * reliably reaches for — `gfx.print`, `os.time`, `spr()`, a star glyph in a
 * score badge — and each message is written FOR THE MODEL, not for the creator:
 * it names the exact replacement rather than describing the problem.
 *
 * Pure TypeScript with no dependencies on purpose. It runs inside React Native
 * (Metro cannot bundle a native Lua), inside the API, and in CI.
 *
 * The member lists below are transcribed from the luaL_Reg tables in
 * firmware/vupp/components/apprt/vupp_apprt_api.c:917-975 — that file is
 * authoritative. M3 generates this from the C so it cannot drift.
 */
import { APP_PALETTE_MAX } from './protocol'

// ---- the engine's actual surface --------------------------------------------

/** k_gfx[] — every member that exists on the gfx table. */
const GFX_MEMBERS = new Set([
  'clear',
  'rect',
  'line',
  'circle',
  'text',
  'sprite',
  'image',
  'map',
  'texcol',
  'vline',
  'shademap',
  'tload',
  'terrain',
  'theight',
  'ssprite',
  'tri',
  'floor',
])

/** The subset that draws from nothing but numbers — no asset files required. */
const GFX_ASSETLESS = new Set(['clear', 'rect', 'line', 'circle', 'text', 'tri'])

/** k_vupp[] plus the tables hung off it (docs, store) and the gated members. */
const VUPP_MEMBERS = new Set([
  'btn',
  'btnp',
  'sfx',
  'tone',
  'on_document',
  'on_command',
  'emit',
  'time',
  'rand',
  'quit',
  'import',
  'docs',
  'store',
  'touch',
  'canvas',
])

/** Assigned by the app rather than provided by the engine. */
const VUPP_LIFECYCLE = new Set(['init', 'update', 'draw', 'on_exit'])

/** Members that are silently absent unless app.json declares the capability. */
const VUPP_CAPABILITY_GATED: Record<string, string> = { touch: 'touch', canvas: 'canvas' }

/** Manifest `capabilities` values the runtime actually looks for. */
export const APP_CAPABILITIES = ['touch', 'canvas'] as const

/**
 * Manifest `category` values. `rewards` is first-party only — the sticker-book
 * app claims it — but it is a real category, so the lint accepts it and the
 * studio prompt simply never offers it.
 */
export const APP_CATEGORIES = ['game', 'creative', 'music', 'learning', 'rewards'] as const

/**
 * Which argument of each assetless call is the palette index, 1-based. How many
 * indices are valid depends on the manifest — apps declare their own palette of
 * up to APP_PALETTE_MAX entries, and half of app-library does.
 */
const COLOR_ARG: Record<string, number> = {
  clear: 1,
  rect: 5,
  line: 5,
  circle: 4,
  text: 4,
  tri: 7,
}

/**
 * How many arguments each assetless call takes, [min, max]. Too few is a
 * guaranteed runtime error — "bad argument #7 to 'tri' (number expected, got
 * no value)" — and the colour, being last on every one of these, is the
 * argument a model actually drops. That was the single most common crash in
 * the first tools/studio/eval.sh baselines.
 */
const GFX_SIGNATURE: Record<string, { min: number; max: number; form: string }> = {
  clear: { min: 1, max: 1, form: 'gfx.clear(color)' },
  rect: { min: 5, max: 6, form: 'gfx.rect(x, y, w, h, color [, filled])' },
  line: { min: 5, max: 5, form: 'gfx.line(x1, y1, x2, y2, color)' },
  circle: { min: 4, max: 5, form: 'gfx.circle(x, y, r, color [, filled])' },
  text: { min: 4, max: 5, form: 'gfx.text(str, x, y, color [, size])' },
  tri: { min: 7, max: 7, form: 'gfx.tri(x0, y0, x1, y1, x2, y2, color)' },
}

/**
 * Globals the sandbox does not open. Reaching for one is a crash, not a
 * warning: vupp_apprt only opens base/math/string/table/utf8 and nils out
 * load/loadfile/dofile afterwards.
 */
const BANNED_CALLS: Record<string, string> = {
  require: 'vupp.import("name")',
  dofile: 'vupp.import("name")',
  loadfile: 'vupp.import("name")',
  load: 'nothing — the sandbox removes it. Write the code directly.',
  collectgarbage: 'nothing — the engine manages memory.',
}

const BANNED_TABLES: Record<string, string> = {
  os: 'vupp.time() for elapsed seconds',
  io: 'vupp.store.set/get to save anything',
  package: 'vupp.import("name")',
  debug: 'nothing — remove it',
  coroutine: 'nothing — the sandbox does not open it. Use a state variable.',
  love: 'the vupp and gfx tables — this is not LOVE',
}

/** PICO-8 / LOVE reflexes that are bare globals here, so they read as nil calls. */
const BANNED_GLOBALS: Record<string, string> = {
  cls: 'gfx.clear(color)',
  pset: 'gfx.rect(x, y, 1, 1, color, true)',
  spr: 'gfx.sprite — which needs an asset file',
  flr: 'math.floor',
  rnd: 'vupp.rand',
  sfx: 'vupp.tone(freq, ms)',
  camera: 'nothing — offset your own coordinates',
  pal: 'nothing — colours are fixed palette indices',
}

// ---- findings ---------------------------------------------------------------

export interface LintProblem {
  /** 'app.json', 'main.lua', 'lib/x.lua' */
  file: string
  /** 1-based; 0 when the problem is about the file as a whole. */
  line: number
  rule: string
  /** Written for the model: what is wrong and what to write instead. */
  message: string
  /** An error blocks the run; a warning rides along with a successful one. */
  severity: 'error' | 'warning'
}

export interface LintOptions {
  /**
   * Whether asset files (sprites, tilemaps, terrain, sfx) can exist. False in
   * the studio, which cannot produce them yet — so gfx.sprite is an error there
   * and perfectly fine in app-library.
   */
  assets?: boolean
  /**
   * How many palette entries the manifest declares. Defaults to the built-in
   * 16 — an app that ships its own `palette` has as many as it lists.
   */
  paletteSize?: number
}

export interface LintResult {
  problems: LintProblem[]
  errors: LintProblem[]
  warnings: LintProblem[]
  ok: boolean
}

// ---- a small Lua scanner -----------------------------------------------------
/*
 * Every rule below needs to know whether a match is real code, the inside of a
 * string, or a comment — otherwise `-- we used to call gfx.print here` fails
 * the build and the model has no idea why. Rather than bolt negative lookarounds
 * onto each regex, tokenize once into spans and blank out what each rule should
 * not see.
 */

type SpanKind = 'code' | 'string' | 'comment'
interface Span {
  kind: SpanKind
  start: number
  end: number
}

/** Level of a long bracket opening at `at`, or null if that isn't one. */
function longBracketLevel(src: string, at: number): number | null {
  if (src[at] !== '[') return null
  let j = at + 1
  let level = 0
  while (src[j] === '=') {
    level += 1
    j += 1
  }
  return src[j] === '[' ? level : null
}

function scanLua(src: string): Span[] {
  const spans: Span[] = []
  const push = (kind: SpanKind, start: number, end: number) => {
    if (end > start) spans.push({ kind, start, end })
  }

  let i = 0
  let codeStart = 0

  const closeLong = (from: number, level: number): number => {
    const close = `]${'='.repeat(level)}]`
    const at = src.indexOf(close, from)
    return at === -1 ? src.length : at + close.length
  }

  while (i < src.length) {
    const c = src[i]

    // Comment — long form first, since --[[ starts with --.
    if (c === '-' && src[i + 1] === '-') {
      push('code', codeStart, i)
      const commentStart = i
      const level = longBracketLevel(src, i + 2)
      if (level !== null) {
        i = closeLong(i + 3 + level, level)
      } else {
        const nl = src.indexOf('\n', i)
        i = nl === -1 ? src.length : nl
      }
      push('comment', commentStart, i)
      codeStart = i
      continue
    }

    // Long string.
    if (c === '[') {
      const level = longBracketLevel(src, i)
      if (level !== null) {
        push('code', codeStart, i)
        const stop = closeLong(i + 2 + level, level)
        push('string', i, stop)
        i = stop
        codeStart = i
        continue
      }
    }

    // Short string. An unterminated one is a syntax error anyway; treat the
    // rest of the line as the string so the scanner still terminates.
    if (c === '"' || c === "'") {
      push('code', codeStart, i)
      let j = i + 1
      while (j < src.length) {
        if (src[j] === '\\') {
          j += 2
          continue
        }
        if (src[j] === c || src[j] === '\n') break
        j += 1
      }
      const stop = Math.min(j + 1, src.length)
      push('string', i, stop)
      i = stop
      codeStart = i
      continue
    }

    i += 1
  }
  push('code', codeStart, src.length)
  return spans
}

/** The source with every span NOT in `keep` replaced by spaces, offsets intact. */
function view(src: string, spans: Span[], keep: SpanKind[]): string {
  const out = src.split('')
  for (const s of spans) {
    if (keep.includes(s.kind)) continue
    for (let i = s.start; i < s.end; i++) {
      if (out[i] !== '\n') out[i] = ' '
    }
  }
  return out.join('')
}

function lineIndex(src: string): number[] {
  const starts = [0]
  for (let i = 0; i < src.length; i++) if (src[i] === '\n') starts.push(i + 1)
  return starts
}

function lineAt(starts: number[], offset: number): number {
  let lo = 0
  let hi = starts.length - 1
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1
    if ((starts[mid] ?? 0) <= offset) lo = mid
    else hi = mid - 1
  }
  return lo + 1
}

/**
 * Top-level, comma-separated argument text of the call whose `(` is at `open`.
 * Returns null when the parens don't balance (the file won't parse anyway).
 */
function callArgs(src: string, open: number): string[] | null {
  let depth = 0
  let start = open + 1
  const args: string[] = []
  for (let i = open; i < src.length; i++) {
    const c = src[i]
    if (c === '(' || c === '{' || c === '[') {
      depth += 1
      if (depth === 1) start = i + 1
    } else if (c === ')' || c === '}' || c === ']') {
      depth -= 1
      if (depth === 0) {
        args.push(src.slice(start, i))
        return args.length === 1 && args[0]?.trim() === '' ? [] : args
      }
    } else if (c === ',' && depth === 1) {
      args.push(src.slice(start, i))
      start = i + 1
    }
  }
  return null
}

/** Names the file defines itself, so a local `load` isn't the sandbox's `load`. */
function localNames(code: string): Set<string> {
  const names = new Set<string>()
  const patterns = [
    /\blocal\s+function\s+([A-Za-z_]\w*)/g,
    /\bfunction\s+([A-Za-z_]\w*)\s*\(/g,
    /\blocal\s+([A-Za-z_][\w\s,]*?)\s*=/g,
  ]
  for (const re of patterns) {
    let m = re.exec(code)
    while (m) {
      for (const raw of (m[1] ?? '').split(',')) {
        const n = raw.trim()
        if (n) names.add(n)
      }
      m = re.exec(code)
    }
  }
  return names
}

// ---- Lua rules ---------------------------------------------------------------

export function lintLua(file: string, src: string, opts: LintOptions = {}): LintProblem[] {
  const assets = opts.assets ?? true
  const paletteSize = opts.paletteSize ?? 16
  const problems: LintProblem[] = []
  const spans = scanLua(src)
  const starts = lineIndex(src)
  const code = view(src, spans, ['code'])
  const live = view(src, spans, ['code', 'string']) // everything but comments
  const defined = localNames(code)

  const add = (
    offset: number,
    rule: string,
    message: string,
    severity: 'error' | 'warning' = 'error',
  ) => problems.push({ file, line: lineAt(starts, offset), rule, message, severity })

  // Bytes the font cannot draw. The 4x6/8x12/12x18 glyph sets cover ASCII
  // 32..127 and nothing else, so a star or an arrow renders as one literal "?"
  // per byte — "* 70" becomes "?70?" and looks like a bug to the creator.
  // Scanned by code point rather than by regex so a surrogate pair reports as
  // the one character the author wrote, not as two halves.
  const seenNonAsciiLines = new Set<number>()
  let offset = 0
  for (const ch of live) {
    if ((ch.codePointAt(0) ?? 0) > 127) {
      const line = lineAt(starts, offset)
      if (!seenNonAsciiLines.has(line)) {
        seenNonAsciiLines.add(line)
        add(
          offset,
          'non-ascii',
          `"${ch}" is not ASCII 32..127. The device font has no glyph for it and draws a literal "?" for every byte, so this renders as visible garbage. Use plain ASCII, or draw the symbol with gfx.circle / gfx.tri / gfx.rect.`,
        )
      }
    }
    offset += ch.length
  }
  let m: RegExpExecArray | null = null

  // gfx members.
  const gfxRe = /\bgfx\s*\.\s*([A-Za-z_]\w*)/g
  m = gfxRe.exec(code)
  while (m) {
    const name = m[1] ?? ''
    if (!GFX_MEMBERS.has(name)) {
      add(
        m.index,
        'gfx-unknown',
        `gfx.${name} does not exist and calling it crashes. The whole gfx table is: ${[...GFX_MEMBERS].join(', ')}.`,
      )
    } else if (!assets && !GFX_ASSETLESS.has(name)) {
      add(
        m.index,
        'gfx-needs-assets',
        `gfx.${name} reads from an asset file (a sprite sheet, tilemap or terrain) and this app has none, so it will crash. Draw with gfx.rect, gfx.circle, gfx.line, gfx.tri and gfx.text instead.`,
      )
    }
    m = gfxRe.exec(code)
  }

  // vupp members.
  const vuppRe = /\bvupp\s*\.\s*([A-Za-z_]\w*)/g
  m = vuppRe.exec(code)
  while (m) {
    const name = m[1] ?? ''
    const assignment = /^\s*=[^=]/.test(code.slice(m.index + m[0].length))
    if (VUPP_LIFECYCLE.has(name)) {
      // vupp.init/update/draw/on_exit are the app's to define.
    } else if (!VUPP_MEMBERS.has(name)) {
      add(
        m.index,
        'vupp-unknown',
        `vupp.${name} does not exist. The vupp table is: ${[...VUPP_MEMBERS].join(', ')}, plus the callbacks you define (init, update, draw, on_exit).`,
      )
    } else if (assignment) {
      add(
        m.index,
        'vupp-overwrite',
        `Assigning to vupp.${name} replaces an engine function. Use a local variable instead.`,
      )
    } else if (name === 'sfx' && !assets) {
      add(
        m.index,
        'vupp-needs-assets',
        'vupp.sfx plays a WAV from the app package and this app has none. Use vupp.tone(freq, ms, vol, wave) instead — it needs no files.',
      )
    }
    m = vuppRe.exec(code)
  }

  // START never reaches the app: the engine owns it for the pause menu, so the
  // button simply never reads as pressed and the app looks broken.
  const startRe = /\bvupp\s*\.\s*btnp?\s*\(\s*['"]start['"]/g
  m = startRe.exec(live)
  while (m) {
    add(
      m.index,
      'btn-start',
      'The engine owns START for its pause menu, so vupp.btn("start") is never true. Use "a", "b" or "select".',
    )
    m = startRe.exec(live)
  }

  // Sandbox holes, skipping anything the file defines itself.
  for (const [name, instead] of Object.entries(BANNED_CALLS)) {
    if (defined.has(name)) continue
    const re = new RegExp(`\\b${name}\\s*[("'{]`, 'g')
    m = re.exec(code)
    while (m) {
      add(m.index, 'sandbox', `${name} is not available in the Vupp sandbox — use ${instead}`)
      m = re.exec(code)
    }
  }
  for (const [name, instead] of Object.entries(BANNED_TABLES)) {
    if (defined.has(name)) continue
    const re = new RegExp(`\\b${name}\\s*\\.\\s*[A-Za-z_]`, 'g')
    m = re.exec(code)
    while (m) {
      add(
        m.index,
        'sandbox',
        `The ${name} table does not exist in the Vupp sandbox — use ${instead}`,
      )
      m = re.exec(code)
    }
  }
  for (const [name, instead] of Object.entries(BANNED_GLOBALS)) {
    if (defined.has(name)) continue
    const re = new RegExp(`(^|[^\\w.:])${name}\\s*\\(`, 'g')
    m = re.exec(code)
    while (m) {
      add(
        m.index + (m[1]?.length ?? 0),
        'not-pico8',
        `${name}() is PICO-8/LOVE, not Vupp, and is nil here — use ${instead}`,
      )
      m = re.exec(code)
    }
  }

  // Palette indices and text size, from the literal arguments only — anything
  // computed is the app's business.
  for (const [name, colorArg] of Object.entries(COLOR_ARG)) {
    const re = new RegExp(`\\bgfx\\s*\\.\\s*${name}\\s*\\(`, 'g')
    m = re.exec(code)
    while (m) {
      const args = callArgs(code, m.index + m[0].length - 1)
      if (args) {
        // Argument count, but only when every argument is a plain expression.
        // `gfx.rect(table.unpack(r))` passes four values through one argument
        // and is perfectly valid, so counting commas would be wrong there.
        const sig = GFX_SIGNATURE[name]
        const spread = args.some((a) => /\bunpack\b|\.\.\./.test(a))
        if (sig && !spread && (args.length < sig.min || args.length > sig.max)) {
          add(
            m.index,
            'gfx-arity',
            `gfx.${name} takes ${sig.min === sig.max ? sig.min : `${sig.min} or ${sig.max}`} arguments but got ${args.length}, which crashes with "bad argument". The signature is ${sig.form} — the colour is the one that gets left off.`,
          )
        }

        const color = args[colorArg - 1]?.trim()
        // 255 is the transparent sentinel in .vsp assets, never a colour.
        if (color && /^\d+$/.test(color) && Number(color) >= paletteSize && Number(color) !== 255) {
          add(
            m.index,
            'palette-range',
            `Colour ${color} is outside this app's palette of ${paletteSize} (0..${paletteSize - 1}), so gfx.${name} draws nothing. Colours are palette indices, not hex — declare more in app.json's "palette" if you need them.`,
          )
        }
        if (name === 'text') {
          const size = args[4]?.trim()
          if (size && /^\d+$/.test(size) && (Number(size) < 1 || Number(size) > 3)) {
            add(
              m.index,
              'text-size',
              `gfx.text size ${size} does not exist — only 1, 2 and 3 do. Anything a child reads wants 2 or 3.`,
            )
          }
        }
      }
      m = re.exec(code)
    }
  }

  return problems
}

// ---- manifest ---------------------------------------------------------------

export interface ManifestLintOptions extends LintOptions {
  /** The engine version the target runtime provides. */
  engineVersion: number
  /** Slug the package must carry (the studio pins this to 'draft'). */
  requireSlug?: string
}

export function lintManifest(src: string, opts: ManifestLintOptions): LintProblem[] {
  const file = 'app.json'
  const problems: LintProblem[] = []
  const add = (rule: string, message: string, severity: 'error' | 'warning' = 'error') =>
    problems.push({ file, line: 0, rule, message, severity })

  let manifest: Record<string, unknown>
  try {
    const parsed: unknown = JSON.parse(src)
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      add('manifest-shape', 'app.json must be a JSON object.')
      return problems
    }
    manifest = parsed as Record<string, unknown>
  } catch (e) {
    add(
      'manifest-json',
      `app.json is not valid JSON: ${e instanceof Error ? e.message : String(e)}`,
    )
    return problems
  }

  const { requireSlug, engineVersion } = opts

  if (requireSlug && manifest.slug !== requireSlug) {
    add(
      'manifest-slug',
      `"slug" must be exactly "${requireSlug}" — the preview device installs the app under that name.`,
    )
  }
  if (typeof manifest.title !== 'string' || !manifest.title.trim()) {
    add(
      'manifest-title',
      '"title" must be a non-empty string — it is the name on the launcher tile.',
    )
  }
  if (typeof manifest.version !== 'string') {
    add('manifest-version', '"version" must be a string, e.g. "1.0.0".')
  }
  if (!APP_CATEGORIES.includes(manifest.category as (typeof APP_CATEGORIES)[number])) {
    add('manifest-category', `"category" must be one of: ${APP_CATEGORIES.join(', ')}.`)
  }
  const fps = manifest.fps
  if (typeof fps !== 'number' || !Number.isInteger(fps) || fps < 1 || fps > 60) {
    add('manifest-fps', '"fps" must be a whole number between 1 and 60. Use 30.')
  }

  const caps = manifest.capabilities
  if (caps !== undefined && !Array.isArray(caps)) {
    add('manifest-capabilities', '"capabilities" must be an array of strings.')
  } else if (Array.isArray(caps)) {
    for (const c of caps) {
      if (!APP_CAPABILITIES.includes(c as (typeof APP_CAPABILITIES)[number])) {
        add(
          'manifest-capabilities',
          `"${String(c)}" is not a capability. The only ones are: ${APP_CAPABILITIES.join(', ')}.`,
        )
      }
    }
  }

  const palette = manifest.palette
  if (palette !== undefined) {
    if (!Array.isArray(palette)) {
      add('manifest-palette', '"palette" must be an array of "#rrggbb" strings.')
    } else {
      if (palette.length > APP_PALETTE_MAX) {
        add(
          'manifest-palette',
          `"palette" has ${palette.length} entries; the engine reads at most ${APP_PALETTE_MAX}.`,
        )
      }
      const bad = palette.findIndex((c) => typeof c !== 'string' || !/^#[0-9a-fA-F]{6}$/.test(c))
      if (bad !== -1) {
        add(
          'manifest-palette',
          `"palette" entry ${bad} is ${JSON.stringify(palette[bad])}; every entry must be "#rrggbb".`,
        )
      }
    }
  }

  const minEngine = manifest.min_engine
  if (typeof minEngine !== 'number') {
    add('manifest-min-engine', `"min_engine" must be a number. Use ${engineVersion}.`)
  } else if (minEngine > engineVersion) {
    add(
      'manifest-min-engine',
      `"min_engine" is ${minEngine} but this engine is v${engineVersion}, so the app is refused before it starts. Use ${engineVersion}.`,
    )
  }

  return problems
}

// ---- the whole project -------------------------------------------------------

export interface ProjectLintOptions extends ManifestLintOptions {}

/**
 * Check a complete app: the manifest, every Lua file, and the things only
 * visible across both — a capability used but not declared, a missing
 * vupp.draw.
 */
export function lintProject(files: Record<string, string>, opts: ProjectLintOptions): LintResult {
  const problems: LintProblem[] = []

  const manifestSrc = files['app.json']
  if (manifestSrc === undefined) {
    problems.push({
      file: 'app.json',
      line: 0,
      rule: 'missing-manifest',
      message: 'Every app needs an app.json. Include it in the file set.',
      severity: 'error',
    })
  } else {
    problems.push(...lintManifest(manifestSrc, opts))
  }

  // Colour range depends on the app's own palette, so read it before the Lua.
  let declared: string[] = []
  let paletteSize = opts.paletteSize ?? 16
  try {
    const parsed = JSON.parse(manifestSrc ?? '{}')
    if (Array.isArray(parsed?.capabilities)) declared = parsed.capabilities.map(String)
    if (Array.isArray(parsed?.palette) && parsed.palette.length > 0) {
      paletteSize = Math.min(parsed.palette.length, APP_PALETTE_MAX)
    }
  } catch {
    /* already reported by lintManifest */
  }

  const lua = Object.keys(files)
    .filter((p) => p.endsWith('.lua'))
    .sort()
  if (!files['main.lua']) {
    problems.push({
      file: 'main.lua',
      line: 0,
      rule: 'missing-main',
      message: 'Every app needs a main.lua. Include it in the file set.',
      severity: 'error',
    })
  }
  for (const path of lua)
    problems.push(...lintLua(path, files[path] ?? '', { ...opts, paletteSize }))

  // Cross-file: a capability used but not declared is the nastiest failure in
  // the engine, because the member is simply absent rather than erroring — the
  // crash reads "attempt to index a nil value (field 'touch')" and points at
  // the call site rather than at the manifest.
  const allCode = lua.map((p) => files[p]).join('\n')
  for (const [member, capability] of Object.entries(VUPP_CAPABILITY_GATED)) {
    const used = new RegExp(`\\bvupp\\s*\\.\\s*${member}\\b`).test(allCode)
    if (used && !declared.includes(capability)) {
      problems.push({
        file: 'app.json',
        line: 0,
        rule: 'capability-undeclared',
        message: `The app calls vupp.${member} but app.json does not list "${capability}" in "capabilities". The engine only injects that member when the capability is declared, so the call crashes with "attempt to index a nil value". Add "${capability}" to capabilities.`,
        severity: 'error',
      })
    }
  }

  if (
    files['main.lua'] &&
    !/\bvupp\s*\.\s*draw\s*[=(]|function\s+vupp\s*\.\s*draw\b/.test(allCode)
  ) {
    problems.push({
      file: 'main.lua',
      line: 0,
      rule: 'missing-draw',
      message:
        'No vupp.draw is defined, so the screen never renders. Define function vupp.draw(gfx).',
      severity: 'error',
    })
  }

  const errors = problems.filter((p) => p.severity === 'error')
  const warnings = problems.filter((p) => p.severity === 'warning')
  return { problems, errors, warnings, ok: errors.length === 0 }
}

/** Render problems as the compact, positional text a model can act on. */
export function formatLintProblems(problems: LintProblem[]): string {
  return problems
    .map((p) => `${p.file}${p.line ? `:${p.line}` : ''} [${p.rule}] ${p.message}`)
    .join('\n')
}
