import {
  BUDGETS,
  ENGINE_API,
  engineReference,
  listReferenceApps,
  MANIFEST,
  NEGATIVE_LIST,
  REFERENCE_SLUGS,
  REFERENCE_TOPICS,
  type ReferenceTopic,
  readReferenceApp,
  SKELETON,
} from '@vupp/app-reference'

import { type Ctx, emit } from '../output.js'

/**
 * The reading material, offline.
 *
 * Exactly the corpus the in-app studio agent reads through its own tools —
 * eleven apps that run on the hardware, written against this engine, filtered
 * by vupp-lint so every one of them could have been written by an AI with no
 * asset pipeline. Handing over an app that draws with gfx.sprite would teach a
 * call that crashes here.
 */

export async function cmdReferenceList(ctx: Ctx): Promise<number> {
  const { apps } = listReferenceApps()
  emit(ctx, { apps }, () =>
    apps
      .map(
        (a) =>
          `${a.slug.padEnd(12)} ${a.category.padEnd(9)} ${String(a.lines).padStart(4)} lines  ${a.title}\n` +
          `             ${a.summary}`,
      )
      .join('\n'),
  )
  return 0
}

export async function cmdReferenceShow(ctx: Ctx, slug: string, file?: string): Promise<number> {
  const result = readReferenceApp(slug, file)
  if (!result.ok) {
    emit(ctx, result, () => result.error)
    return 1
  }
  if ('content' in result) {
    emit(ctx, result, () => result.content)
    return 0
  }
  emit(ctx, result, () =>
    Object.entries(result.files)
      .map(([path, content]) => `${'='.repeat(60)}\n${path}\n${'='.repeat(60)}\n${content}`)
      .join('\n'),
  )
  return 0
}

/**
 * The long-form topics, plus the blocks that are always in the studio agent's
 * prompt. An AI reading this from outside has no system prompt carrying them,
 * so `vupp docs` with no topic prints the whole thing — that is its equivalent
 * of the front-loaded prefix.
 */
const FULL_TOPICS = ['api', 'not-available', 'budget-limits', 'manifest', 'skeleton'] as const
type FullTopic = (typeof FULL_TOPICS)[number]

const ALWAYS: Record<FullTopic, string> = {
  api: ENGINE_API,
  'not-available': NEGATIVE_LIST,
  'budget-limits': BUDGETS,
  manifest: MANIFEST,
  skeleton: SKELETON,
}

export const DOC_TOPICS = [...FULL_TOPICS, ...REFERENCE_TOPICS]

export async function cmdDocs(ctx: Ctx, topic?: string): Promise<number> {
  if (!topic) {
    const everything = [
      ALWAYS.api,
      ALWAYS['not-available'],
      ALWAYS['budget-limits'],
      ALWAYS.manifest,
      ALWAYS.skeleton,
    ].join('\n\n')
    emit(ctx, { topic: 'all', reference: everything, topics: DOC_TOPICS }, () => everything)
    return 0
  }

  if (topic in ALWAYS) {
    const reference = ALWAYS[topic as FullTopic]
    emit(ctx, { topic, reference }, () => reference)
    return 0
  }
  if ((REFERENCE_TOPICS as string[]).includes(topic)) {
    const reference = engineReference(topic as ReferenceTopic)
    emit(ctx, { topic, reference }, () => reference)
    return 0
  }

  emit(
    ctx,
    { ok: false, error: `no topic "${topic}"`, topics: DOC_TOPICS },
    () => `No topic "${topic}". Try: ${DOC_TOPICS.join(', ')}`,
  )
  return 1
}

export { REFERENCE_SLUGS }
