import { unzipSync, zipSync } from 'fflate'

/**
 * The zip a creator hands to a parent (docs/17-studio.md "Distribution").
 *
 * This is the handoff mechanism, deliberately chosen over invite tokens or
 * share codes: a therapist finishes a game, taps share, and it goes through
 * Messages or Mail or AirDrop like any other file. Nothing to sign up for,
 * no link that expires, no server that has to know the two people involved —
 * which matters because the two people are frequently in different families.
 *
 * The zip holds SOURCE, in the same layout as `app-library/<slug>/`:
 *
 *   app.json      the manifest
 *   main.lua      the program
 *   lib/*.lua     anything it imports
 *   studio.json   who made it and what they said about it
 *
 * Not a packed .tar. Keeping it as source means the API stays the only thing
 * that produces a package, so a zip can never smuggle bytes past the
 * conversion pipeline; it also makes the artifact re-importable, editable, and
 * droppable straight into app-library/ as a first-party app.
 */

/** Sidecar describing where the app came from. Everything in it is advisory. */
export interface StudioMeta {
  /** What the creator called it. */
  title?: string
  /** Free text — "Grandma", "Sam's OT". A label, never an identity. */
  author?: string
  /** A sentence from the creator to whoever receives it. */
  note?: string
  /** Written by the exporting app so a future reader knows what it is. */
  kind: 'vupp-studio-app'
  version: 1
}

export const STUDIO_META_PATH = 'studio.json'

/**
 * A fixed timestamp for every entry. Zip stores DOS dates, which start at
 * 1980, and the conversion happens in LOCAL time — so midnight on the 1st
 * reads as 1979 anywhere behind UTC and is rejected. Noon cannot cross the
 * year boundary in either direction.
 */
const ZIP_EPOCH = Date.UTC(1980, 0, 1, 12)

/** Paths a zip may contribute to a project; everything else is ignored. */
const SOURCE_PATH_RE = /^(app\.json|main\.lua|lib\/[A-Za-z0-9_-]+\.lua)$/

export interface ReadZipResult {
  files: Record<string, string>
  meta: StudioMeta | null
  /** Entries that were present but not part of an app, for an honest summary. */
  ignored: string[]
}

export class ZipReadError extends Error {
  constructor(
    readonly code: string,
    /** Written for a non-technical reader. */
    readonly human: string,
  ) {
    super(human)
    this.name = 'ZipReadError'
  }
}

/**
 * Strip the wrapper directory that every desktop zip tool adds.
 *
 * "Compress" on macOS and "Send to > Compressed folder" on Windows both wrap
 * the contents in a folder named after it, and a creator who zips their app
 * folder gets `Frog Hop/app.json` rather than `app.json`. Refusing that would
 * be the single most likely way this feature fails in someone's hands, so
 * peel exactly one common prefix when there is one.
 */
function stripWrapper(names: string[]): (name: string) => string {
  const real = names.filter((n) => !isJunk(n) && !isUnsafe(n) && !n.endsWith('/'))
  if (real.length === 0) return (n) => n
  const first = real[0] as string
  const slash = first.indexOf('/')
  if (slash === -1) return (n) => n
  const prefix = first.slice(0, slash + 1)
  return real.every((n) => n.startsWith(prefix)) ? (n) => n.slice(prefix.length) : (n) => n
}

/**
 * Metadata the archiver added and nobody chose. Dropped silently, because
 * telling someone their zip contained a .DS_Store is noise.
 */
function isJunk(name: string): boolean {
  return (
    name.startsWith('__MACOSX/') ||
    name.split('/').some((part) => part === '.DS_Store' || part === 'Thumbs.db')
  )
}

/**
 * A path that would write outside the app. Reported rather than dropped
 * quietly: a zip carrying one is either broken or hostile, and in both cases
 * the person deserves to be told something was left out.
 */
function isUnsafe(name: string): boolean {
  return name.startsWith('/') || name.split('/').includes('..')
}

export function readAppZip(bytes: Uint8Array): ReadZipResult {
  let entries: Record<string, Uint8Array>
  try {
    entries = unzipSync(bytes)
  } catch {
    throw new ZipReadError(
      'not_a_zip',
      "That file isn't a zip, or it's damaged. Ask for it to be sent again.",
    )
  }

  const names = Object.keys(entries)
  const unwrap = stripWrapper(names)
  const decoder = new TextDecoder()
  const files: Record<string, string> = {}
  const ignored: string[] = []
  let meta: StudioMeta | null = null

  for (const name of names) {
    if (isJunk(name) || name.endsWith('/')) continue
    if (isUnsafe(name)) {
      ignored.push(name)
      continue
    }
    const rel = unwrap(name)
    const data = entries[name]
    if (!data) continue

    if (rel === STUDIO_META_PATH) {
      try {
        meta = JSON.parse(decoder.decode(data)) as StudioMeta
      } catch {
        /* a broken sidecar costs nothing — the app is what matters */
      }
      continue
    }
    if (!SOURCE_PATH_RE.test(rel)) {
      ignored.push(rel)
      continue
    }
    files[rel] = decoder.decode(data)
  }

  if (!files['app.json'] || !files['main.lua']) {
    throw new ZipReadError(
      'not_an_app',
      "That zip doesn't have a Vupp app in it. It should contain the app's settings and program files.",
    )
  }
  return { files, meta, ignored }
}

/**
 * Build the zip to hand over. Deterministic for the same input — same reason
 * the tar writer is: two exports of an unchanged app should be the same file.
 */
export function writeAppZip(files: Record<string, string>, meta: StudioMeta): Uint8Array {
  const encoder = new TextEncoder()
  const entries: Record<string, Uint8Array> = {}
  for (const path of Object.keys(files).sort()) {
    entries[path] = encoder.encode(files[path] ?? '')
  }
  entries[STUDIO_META_PATH] = encoder.encode(`${JSON.stringify(meta, null, 2)}\n`)
  // Pinned for the same reason the tar writer pins mtime: identical input,
  // identical bytes. Not 0 — zip stores DOS timestamps, which only reach back
  // to 1980, and fflate rejects anything earlier.
  return zipSync(entries, { level: 6, mtime: ZIP_EPOCH })
}
