import { parseArgs } from 'node:util'

import { cmdDoctor } from './commands/doctor.js'
import { cmdInit } from './commands/init.js'
import { cmdLint } from './commands/lint.js'
import { cmdPackage } from './commands/package.js'
import { cmdPlay } from './commands/play.js'
import { cmdPlaytest } from './commands/playtest.js'
import { cmdDocs, cmdReferenceList, cmdReferenceShow, DOC_TOPICS } from './commands/reference.js'
import { cmdRun } from './commands/run.js'
import type { Ctx } from './output.js'
import { ProjectError } from './project.js'
import { SimAssetError } from './sim/assets.js'
import { BrowserError } from './sim/browser.js'

/**
 * vupp — build a game for a Vupp handheld from a terminal.
 *
 * Raw primitives, deliberately: read the docs, read a reference app, write
 * files, check them, run them on the real firmware, press buttons and look at
 * the screen, hand the result over. There is no agent in here. The reasoning
 * belongs to whoever is driving — a person, or the AI reading
 * sdk/claude-plugin's skill (docs/18-game-sdk.md).
 *
 * Every command takes --json, and that is the interface an AI should use: a
 * value to branch on rather than prose to parse. Progress goes to stderr so a
 * --json run stays one parseable document.
 */

const USAGE = `vupp — build and playtest games for the Vupp handheld

  vupp doctor [--refresh]            fetch the simulator and a browser, check everything
  vupp init [dir] [--from <slug>]    start an app (optionally from a reference app)
  vupp docs [topic]                  the engine reference; no topic prints all of it
  vupp reference list                the apps you can read as worked examples
  vupp reference show <slug> [file]  one of them
  vupp lint [dir]                    vupp-lint, the check that runs before anything runs
  vupp run [dir]                     put it on the simulator and report what happened
  vupp playtest [dir] --goal <text> --steps <json|file>
                                     press buttons, write PNG frames, report what changed
  vupp play [dir|game.zip]           PLAY IT YOURSELF in a browser — real keyboard,
                                     already loaded, reloads on every edit. Not headless.
  vupp package [dir] [-o out.zip]    the zip a parent imports into the Vupp app

Options
  --json                             machine-readable output (use this from an AI)
  --quiet                            no progress on stderr
  -h, --help                         this

Topics: ${DOC_TOPICS.join(', ')}

Environment
  VUPP_SIM_URL      where to download the simulator from
  VUPP_SIM_DIR      a local directory of simulator assets (overrides the above)
  VUPP_CHROME       a Chromium-based browser to run the simulator in
  VUPP_CACHE_DIR    where downloads are cached (default ~/.cache/vupp)
`

async function main(argv: string[]): Promise<number> {
  const { values, positionals } = parseArgs({
    args: argv,
    allowPositionals: true,
    strict: false,
    options: {
      json: { type: 'boolean', default: false },
      quiet: { type: 'boolean', default: false },
      help: { type: 'boolean', short: 'h', default: false },
      from: { type: 'string' },
      title: { type: 'string' },
      force: { type: 'boolean', default: false },
      goal: { type: 'string' },
      steps: { type: 'string' },
      frames: { type: 'string' },
      out: { type: 'string', short: 'o' },
      author: { type: 'string' },
      note: { type: 'string' },
      refresh: { type: 'boolean', default: false },
      port: { type: 'string' },
      host: { type: 'string' },
    },
  })

  const ctx: Ctx = { json: Boolean(values.json), quiet: Boolean(values.quiet) }
  const [command, ...rest] = positionals

  if (values.help || !command) {
    process.stdout.write(USAGE)
    return command ? 0 : 1
  }

  switch (command) {
    case 'doctor':
      return cmdDoctor(ctx, { refresh: Boolean(values.refresh) })

    case 'init':
      return cmdInit(ctx, rest[0] ?? '.', {
        from: values.from as string | undefined,
        title: values.title as string | undefined,
        force: Boolean(values.force),
      })

    case 'docs':
      return cmdDocs(ctx, rest[0])

    case 'reference': {
      const sub = rest[0]
      if (sub === 'list' || sub === undefined) return cmdReferenceList(ctx)
      if (sub === 'show') {
        if (!rest[1]) throw new ProjectError('vupp reference show <slug> [file]')
        return cmdReferenceShow(ctx, rest[1], rest[2])
      }
      throw new ProjectError(`unknown: vupp reference ${sub}`)
    }

    case 'lint':
      return cmdLint(ctx, rest[0] ?? '.')

    case 'run':
      return cmdRun(ctx, rest[0] ?? '.')

    case 'playtest': {
      if (!values.goal)
        throw new ProjectError('vupp playtest needs --goal "what you want to find out"')
      if (!values.steps) {
        throw new ProjectError(
          'vupp playtest needs --steps, as inline JSON or a path to a JSON file. For example:\n' +
            `  --steps '[{"label":"sit still","wait_ms":800,"shot":true},` +
            `{"press":["a"],"hold_ms":120,"wait_ms":400,"shot":true}]'`,
        )
      }
      return cmdPlaytest(ctx, rest[0] ?? '.', {
        goal: values.goal as string,
        steps: values.steps as string,
        outDir: values.frames as string | undefined,
      })
    }

    case 'play':
      return cmdPlay(ctx, rest[0] ?? '.', {
        port: values.port ? Number(values.port) : undefined,
        host: values.host as string | undefined,
        // parseArgs has no --no-x negation; with strict:false it lands here.
        open: !values['no-open'],
      })

    case 'package':
      return cmdPackage(ctx, rest[0] ?? '.', {
        out: values.out as string | undefined,
        author: values.author as string | undefined,
        note: values.note as string | undefined,
      })

    // Reserved so the shape of the CLI does not change when they land. v1 stops
    // at a zip on purpose — see commands/package.ts.
    case 'login':
    case 'publish':
      process.stderr.write(
        `vupp ${command} is not in this release.\n\n` +
          "Publishing an app onto a child's device is a parent-only action, and it happens in\n" +
          'the Vupp app. Run `vupp package` and send them the zip.\n',
      )
      return 2

    default:
      process.stderr.write(`unknown command: ${command}\n\n${USAGE}`)
      return 1
  }
}

main(process.argv.slice(2))
  .then((code) => process.exit(code))
  .catch((err) => {
    if (
      err instanceof ProjectError ||
      err instanceof SimAssetError ||
      err instanceof BrowserError
    ) {
      process.stderr.write(`${err.message}\n`)
      process.exit(1)
    }
    if (err && typeof err === 'object' && 'issues' in err) {
      // A zod failure on --steps. Say which step and what was wrong with it.
      process.stderr.write(`${JSON.stringify((err as { issues: unknown }).issues, null, 2)}\n`)
      process.exit(1)
    }
    process.stderr.write(`${err instanceof Error ? (err.stack ?? err.message) : String(err)}\n`)
    process.exit(1)
  })
