import { spawn } from 'node:child_process'
import { createHash } from 'node:crypto'
import { watch as fsWatch } from 'node:fs'
import { readFile } from 'node:fs/promises'
import { resolve } from 'node:path'

import { readAppZip, ZipReadError } from '@vupp/app-package'

import { type Ctx, emit, progress, warn } from '../output.js'
import { lint, lintFailure, ProjectError, readProject, titleOf } from '../project.js'
import { resolveSimAssets } from '../sim/assets.js'
import { PLAY_SHELL_HTML, PLAY_SHELL_JS } from '../sim/playShell.js'
import { serveAssets } from '../sim/serve.js'

/**
 * Play the game yourself.
 *
 * `vupp run` and `vupp playtest` are checks: does it start, does it draw, does
 * a scripted press do what the model expected. None of them can answer the
 * question that actually decides whether an app ships — is it any fun for the
 * child it was made for. That needs hands on the buttons, so this is
 * deliberately NOT headless: it serves the simulator and prints a URL to open.
 *
 * Printing a URL rather than only opening a window is the important part. This
 * gets run inside containers and over SSH constantly, where there is no browser
 * to open and the person is on another machine entirely; a command that could
 * only launch a local window would simply not work there. So it binds
 * 0.0.0.0, prints the address, and opens a browser as a convenience when it can.
 *
 * It stays running and reloads on every edit, which is what makes the
 * describe-change-play loop tight enough to actually iterate in.
 */
export interface PlayOptions {
  port?: number
  open?: boolean
  host?: string
}

export async function cmdPlay(ctx: Ctx, target: string, opts: PlayOptions): Promise<number> {
  const root = resolve(target)
  const fromZip = root.toLowerCase().endsWith('.zip')
  let files = fromZip ? await readZipProject(root) : await readProject(root)

  const checked = lint(files)
  if (!checked.ok) {
    emit(ctx, { ok: false, where: 'check', error: lintFailure(checked) }, () =>
      lintFailure(checked),
    )
    return 1
  }

  const assets = await resolveSimAssets({ onProgress: (m) => progress(ctx, m) })
  let version = hash(files)
  let title = titleOf(files)

  const server = await serveAssets(
    assets.dir,
    {
      // Overlaid ahead of the simulator's own chrome-free index.html, which has
      // no buttons because the phone app draws them.
      '/index.html': { body: PLAY_SHELL_HTML, type: 'text/html; charset=utf-8' },
      '/play.js': { body: PLAY_SHELL_JS, type: 'text/javascript; charset=utf-8' },
      get '/__vupp/app.json'() {
        return { body: JSON.stringify({ title, version, files }), type: 'application/json' }
      },
      get '/__vupp/version'() {
        return { body: JSON.stringify({ version }), type: 'application/json' }
      },
    },
    { port: opts.port ?? 0, host: opts.host ?? '0.0.0.0' },
  )

  // Re-read on any change. Debounced because an editor writing a file is
  // several events, and a half-written main.lua that fails to lint would
  // otherwise flash an error at whoever is playing. A zip is watched too — it
  // is normal to re-package and want the open tab to catch up.
  let debounce: NodeJS.Timeout | null = null
  const watcher = fsWatch(root, fromZip ? {} : { recursive: true }, () => {
    if (debounce) clearTimeout(debounce)
    debounce = setTimeout(async () => {
      try {
        const next = fromZip ? await readZipProject(root) : await readProject(root)
        const nextHash = hash(next)
        if (nextHash === version) return
        const result = lint(next)
        if (!result.ok) {
          warn(`\n${lintFailure(result)}\n`)
          return
        }
        files = next
        title = titleOf(next)
        version = nextHash
        progress(ctx, `reloaded — ${title}`)
      } catch {
        /* mid-save; the next event will catch it */
      }
    }, 250)
  })

  const url = server.url
  emit(
    ctx,
    {
      ok: true,
      url,
      port: server.port,
      title,
      source: fromZip ? 'zip' : 'project',
      watching: root,
    },
    () =>
      [
        '',
        `  Play it:  ${url}`,
        '',
        `  ${title} — arrows move, Z is A, X is B, Enter is START.`,
        fromZip
          ? '  The game is already loaded. Re-package and this tab catches up.'
          : '  Edits reload automatically.',
        '  Press Ctrl+C when you are done.',
        '',
      ].join('\n'),
  )

  if (opts.open !== false) openBrowser(url)

  // Hold the process open; this command ends when the person is finished.
  await new Promise<void>((done) => {
    const stop = () => {
      watcher.close()
      void server.close().then(done)
    }
    process.on('SIGINT', stop)
    process.on('SIGTERM', stop)
  })
  return 0
}

/**
 * Play a packaged game without unpacking it first.
 *
 * The hosted player takes a zip through a file picker, which is right for a
 * person and useless to an AI — it cannot drop a file on a page. This is the
 * same zip, read here and served straight into the simulator, so `vupp play
 * game.zip` opens a browser with the game ALREADY RUNNING and no picker in the
 * way. It is also how you check that what you are about to send someone is
 * actually what they will get.
 *
 * Read with the same reader the phone app imports with, so a zip this accepts
 * is one the app accepts, and a zip it rejects would have failed there too.
 */
async function readZipProject(path: string): Promise<Record<string, string>> {
  let bytes: Buffer
  try {
    bytes = await readFile(path)
  } catch {
    throw new ProjectError(`${path} does not exist.`)
  }
  try {
    return readAppZip(new Uint8Array(bytes)).files
  } catch (err) {
    throw new ProjectError(
      err instanceof ZipReadError ? err.human : `${path} could not be read as a Vupp game.`,
    )
  }
}

function hash(files: Record<string, string>): string {
  const h = createHash('sha256')
  for (const path of Object.keys(files).sort())
    h.update(path)
      .update('\0')
      .update(files[path] ?? '')
  return h.digest('hex').slice(0, 12)
}

/**
 * Best effort, and silent when it fails: in a container there is no browser and
 * that is not an error — the URL was printed, which is the part that matters.
 */
function openBrowser(url: string): void {
  const cmd =
    process.platform === 'darwin' ? 'open' : process.platform === 'win32' ? 'start' : 'xdg-open'
  try {
    const child = spawn(cmd, [url], {
      stdio: 'ignore',
      detached: true,
      shell: process.platform === 'win32',
    })
    child.on('error', () => {})
    child.unref()
  } catch {
    /* printed the URL already */
  }
}
