import { formatLintProblems } from '@vupp/shared'

import { type Ctx, emit } from '../output.js'
import { lint, readProject } from '../project.js'

/**
 * vupp-lint, the check that runs before anything is written.
 *
 * Deliberately the same rules and the same options the parent app uses, because
 * it is the same code (packages/shared/src/lualint.ts). It catches the whole
 * class of mistakes that a model makes confidently and that a Lua parser would
 * happily accept: gfx.sprite with no sprite sheet, a PICO-8 reflex like cls(),
 * a palette index past the end of the app's own palette, a star glyph the
 * device's font renders as "?70?".
 *
 * This is a quality loop, not a safety gate — the security boundary is the Lua
 * sandbox itself, which has no io, no os and no network.
 */
export async function cmdLint(ctx: Ctx, dir: string): Promise<number> {
  const files = await readProject(dir)
  const result = lint(files)

  emit(
    ctx,
    {
      ok: result.ok,
      errors: result.errors,
      warnings: result.warnings,
      files: Object.keys(files).sort(),
    },
    () => {
      const lines: string[] = []
      if (result.errors.length) lines.push(formatLintProblems(result.errors))
      if (result.warnings.length) {
        if (lines.length) lines.push('')
        lines.push('Warnings:', formatLintProblems(result.warnings))
      }
      if (result.ok && !result.warnings.length) lines.push('Clean.')
      return lines.join('\n')
    },
  )

  return result.ok ? 0 : 1
}
