import { existsSync } from 'node:fs'
import { homedir } from 'node:os'
import { join } from 'node:path'

/**
 * Finding something to run the WASM in.
 *
 * The sim renders through SDL2's Emscripten port, which draws to a real canvas
 * — so this needs a browser, not a JS runtime. Chrome is on most machines
 * already, and using the installed one keeps the first run free; only when
 * there is nothing at all do we download Chrome's headless shell (~80 MB),
 * which is why `vupp doctor` exists as a separate command. A 80 MB download
 * that starts in the middle of building someone's game reads as a hang.
 *
 * NOTE the screenshots do NOT come off this canvas. bridge.js reads the
 * indexed 160x240 app canvas straight out of WASM memory and paints it into an
 * offscreen 2D canvas, so what a playtest returns is the app's own coordinate
 * space, exactly as apps-internal/studio-sim does it for the phone.
 */

const INSTALLED = [
  // macOS
  '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  '/Applications/Chromium.app/Contents/MacOS/Chromium',
  '/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge',
  // Linux
  '/usr/bin/google-chrome',
  '/usr/bin/google-chrome-stable',
  '/usr/bin/chromium',
  '/usr/bin/chromium-browser',
  '/usr/bin/microsoft-edge',
  // Windows
  'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe',
  'C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe',
]

export const BROWSER_CACHE = join(
  process.env.VUPP_CACHE_DIR ?? join(homedir(), '.cache', 'vupp'),
  'browser',
)

export class BrowserError extends Error {}

export interface BrowserChoice {
  executablePath: string
  source: 'env' | 'installed' | 'downloaded'
}

/** Find a browser without installing anything. */
export async function findBrowser(): Promise<BrowserChoice | null> {
  const fromEnv = process.env.VUPP_CHROME ?? process.env.CHROME_PATH
  if (fromEnv) {
    if (!existsSync(fromEnv)) {
      throw new BrowserError(`VUPP_CHROME points at ${fromEnv}, which does not exist.`)
    }
    return { executablePath: fromEnv, source: 'env' }
  }
  for (const path of INSTALLED) {
    if (existsSync(path)) return { executablePath: path, source: 'installed' }
  }
  return findDownloaded()
}

async function findDownloaded(): Promise<BrowserChoice | null> {
  try {
    // Imported lazily: on a machine with Chrome installed this module is never
    // needed, and it pulls in a fair amount of tarball/zip machinery.
    const { computeExecutablePath, Browser } = await import('@puppeteer/browsers')
    const executablePath = computeExecutablePath({
      browser: Browser.CHROMEHEADLESSSHELL,
      buildId: process.env.VUPP_CHROME_BUILD ?? PINNED_BUILD,
      cacheDir: BROWSER_CACHE,
    })
    return existsSync(executablePath) ? { executablePath, source: 'downloaded' } : null
  } catch {
    return null
  }
}

/**
 * Pinned so two machines run the same renderer. Unpinning it would make "the
 * playtest looked different on your laptop" a thing that can happen.
 */
const PINNED_BUILD = '131.0.6778.108'

export async function ensureBrowser(
  onProgress: (message: string) => void = () => {},
): Promise<BrowserChoice> {
  const found = await findBrowser()
  if (found) return found

  const { install, Browser, resolveBuildId, detectBrowserPlatform } = await import(
    '@puppeteer/browsers'
  )
  const platform = detectBrowserPlatform()
  if (!platform) {
    throw new BrowserError(
      'No Chrome found and this platform is not one the downloader supports. ' +
        'Install Chrome, or point VUPP_CHROME at a Chromium-based browser.',
    )
  }
  const buildId =
    process.env.VUPP_CHROME_BUILD ??
    (await resolveBuildId(Browser.CHROMEHEADLESSSHELL, platform, PINNED_BUILD).catch(
      () => PINNED_BUILD,
    ))

  onProgress(`no Chrome found — downloading Chrome headless shell ${buildId} (~80 MB, once)`)
  const installed = await install({
    browser: Browser.CHROMEHEADLESSSHELL,
    buildId,
    cacheDir: BROWSER_CACHE,
  })
  return { executablePath: installed.executablePath, source: 'downloaded' }
}

/**
 * Flags that matter, and why.
 *
 * SwiftShader: headless Chrome has no GPU, and without a software GL fallback
 * SDL_CreateRenderer fails inside the WASM and the firmware never boots — which
 * surfaces as a silent timeout rather than an error.
 */
export const CHROME_ARGS = [
  '--headless=new',
  '--no-sandbox',
  '--disable-dev-shm-usage',
  '--use-gl=angle',
  '--use-angle=swiftshader',
  '--enable-unsafe-swiftshader',
  '--disable-background-timer-throttling',
  '--disable-renderer-backgrounding',
  '--disable-backgrounding-occluded-windows',
  '--mute-audio',
  '--window-size=320,480',
]
