/**
 * The sticker catalog — code, not data (docs/16-rewards.md). One source of
 * truth for the server (validation), the parent app (display), and the device
 * app: `node tools/rewards/gen-catalog.mjs` regenerates
 * app-library/rewards/lib/catalog.lua from this file, and CI-friendly tests
 * assert the two stay in sync.
 *
 * `cell` indexes the rewards app's sprite sheet (sprite_cell 24x24, 4 columns
 * — see app-library/rewards/assets and tools/assets/pixelart.mjs). `emoji` is
 * the parent-app stand-in ("zero gamification" on the parent side — names and
 * emoji, not pixel art).
 *
 * Super stickers are never directly pickable: they are minted by spending
 * owned stickers per `recipe` — the saving/investing half of the teachable
 * mechanics (the patience half lives on sticker_picks.wait_until).
 */

export type StickerKind = 'regular' | 'super'

export type Sticker = {
  slug: string
  name: string
  emoji: string
  kind: StickerKind
  cell: number // sprite-sheet cell in the rewards app package
  recipe?: Record<string, number> // super only: {slug: count} to combine
}

