const bySlug = new Map(STICKERS.map((s) => [s.slug, s]))

export const stickerBySlug = (slug: string): Sticker | undefined => bySlug.get(slug)
export const REGULAR_STICKERS = STICKERS.filter((s) => s.kind === 'regular')
export const SUPER_STICKERS = STICKERS.filter((s) => s.kind === 'super')

/** Can `owned` counts pay for this super sticker's recipe? */
export function canCombine(slug: string, owned: Record<string, number>): boolean {
  const sticker = bySlug.get(slug)
  if (sticker?.kind !== 'super' || !sticker.recipe) return false
  return Object.entries(sticker.recipe).every(([part, need]) => (owned[part] ?? 0) >= need)
}
