/**
 * Vupp Studio: the contract between the studio chat route and the parent app
 * (docs/17-studio.md).
 *
 * Unlike the copilot (packages/shared/src/ai.ts), the studio agent has no
 * privileged tools at all — it cannot read family data, touch policy, or issue
 * device commands. Its single write tool targets a sandboxed Lua VM inside a
 * WebView, which is why it writes freely instead of proposing: the human gate
 * moved to the far end of the pipeline, where a parent approves and installs.
 *
 * `write_files` is declared here rather than server-side-only because it
 * EXECUTES ON THE CLIENT: the app owns the project state and the simulator, so
 * the route forwards the call and React Native answers it. Both ends validate
 * against this one schema.
 */
import { z } from 'zod'

/** The draft app's slug inside the preview sim; also its `lib:` doc namespace. */
export const STUDIO_DRAFT_SLUG = 'draft'

/** Paths a studio project may contain, mirroring the app-library source layout. */
export const STUDIO_FILE_PATH_RE = /^(app\.json|main\.lua|lib\/[a-z0-9_-]+\.lua)$/

export const studioFileSchema = z.object({
  /** Relative to the app root, e.g. "main.lua" or "lib/levels.lua". */
  path: z.string().regex(STUDIO_FILE_PATH_RE, 'path must be app.json, main.lua, or lib/<name>.lua'),
  content: z.string().max(256 * 1024),
})
export type StudioFile = z.infer<typeof studioFileSchema>

export const writeFilesInputSchema = z.object({
  /**
   * The COMPLETE set of files the app should have after this call — the
   * project is replaced, not merged. Partial writes would strand a lib/*.lua
   * the model meant to delete, and vupp.import would still load it.
   */
  files: z.array(studioFileSchema).min(1).max(12),
  /**
   * One plain sentence for the creator, describing the CHANGE and not the
   * files: "I made the logs move slower and gave the frog a happier hop."
   */
  note: z.string().min(1).max(200),
})
export type WriteFilesInput = z.infer<typeof writeFilesInputSchema>

/** What the app sends back as the tool result once the draft is running. */
export const writeFilesOutputSchema = z.object({
  ok: z.boolean(),
  /**
   * Present when the write failed. Either vupp-lint's findings (when `where`
   * is 'check', so nothing was written) or the device's own Lua error.
   */
  error: z.string().optional(),
  /** check | load | main chunk | init | update | draw | ... */
  where: z.string().optional(),
  /**
   * Problems that do not stop the app running. It IS on screen; fix these on
   * the next edit rather than immediately calling write_files again.
   */
  warnings: z.array(z.string()).optional(),
})
export type WriteFilesOutput = z.infer<typeof writeFilesOutputSchema>

// ---- The plan ---------------------------------------------------------------
/*
 * A build turn takes minutes and the creator's only evidence that anything is
 * happening used to be a spinner. The plan is the fix: the model says what it
 * is about to do, in the creator's words, and the app renders it as a list that
 * ticks off. It is not scaffolding for the model — it is the progress bar.
 *
 * Which is why `step` is prose about the GAME, not about the work. "Logs that
 * drift across the river" is a step; "implement collision detection" is not.
 */

export const planStepStatus = ['pending', 'active', 'done'] as const

export const planStepSchema = z.object({
  /** What the creator gets, in their language. Never a file or a function. */
  step: z.string().min(1).max(80),
  status: z.enum(planStepStatus),
})
export type PlanStep = z.infer<typeof planStepSchema>

export const updatePlanInputSchema = z.object({
  /**
   * The COMPLETE list every time, same discipline as write_files — the app
   * renders exactly this, so a partial list would silently drop steps.
   *
   * Up to ten because the plan is also the unit of WORK: the model builds one
   * step at a time rather than writing the whole game in one call, so a list
   * of three means three very long silences and a list of eight means eight
   * short ones. Eight short ones is the better wait.
   */
  plan: z.array(planStepSchema).min(2).max(10),
  /** Optional one-liner shown above the list when the plan changes shape. */
  explain: z.string().max(160).optional(),
})
export type UpdatePlanInput = z.infer<typeof updatePlanInputSchema>

// ---- Reading ----------------------------------------------------------------
/*
 * The old harness had no read surface at all: the model's only view of the
 * project was what it had written earlier in the same thread, and its only
 * knowledge of the engine was the static prompt. That is why it one-shot
 * everything — there was nothing else it could do.
 */

export const readProjectOutputSchema = z.object({
  files: z.array(studioFileSchema),
  /** Absent on a project that has never been built. */
  title: z.string().optional(),
})
export type ReadProjectOutput = z.infer<typeof readProjectOutputSchema>

export const editFileInputSchema = z.object({
  path: z.string().regex(STUDIO_FILE_PATH_RE),
  /**
   * Must appear EXACTLY ONCE in the file. An ambiguous match is rejected
   * rather than guessed at — the model can always widen the window.
   */
  old_string: z
    .string()
    .min(1)
    .max(64 * 1024),
  new_string: z.string().max(64 * 1024),
  /** Same contract as write_files: one plain sentence about the change. */
  note: z.string().min(1).max(200),
})
export type EditFileInput = z.infer<typeof editFileInputSchema>

// ---- Playtesting ------------------------------------------------------------
/*
 * The gap docs/17-studio.md M1 named: the studio could tell a blank screen from
 * a drawn one, but it could never press a button and look at what happened. The
 * WebView bridge has live pad injection (the native sim's --script is fixed at
 * launch), so this is a genuine closed loop.
 *
 * Frames come back as PNGs of the 160x240 app canvas and are handed to the
 * model as images. That is the point: no amount of "distinct=8 nonbg=4513" can
 * say the score is drawn on top of the player.
 */

/** START is absent on purpose — the engine owns it for the pause menu. */
export const STUDIO_PAD_BUTTONS = ['up', 'down', 'left', 'right', 'a', 'b', 'select'] as const
export type StudioPadButton = (typeof STUDIO_PAD_BUTTONS)[number]

/**
 * Button bits — must match VUPP_PAD_* in components/board/include/vupp_board.h.
 *
 * Whoever drives the simulator resolves names to a mask before sending it, so
 * the bridge in the page stays a dumb sensor and the bitmask has exactly one
 * definition. There are now two drivers — the app (apps/mobile/src/studio) and
 * the CLI (packages/cli) — which is precisely why this lives here rather than
 * next to either of them.
 */
export const STUDIO_PAD_MASK = {
  up: 1 << 0,
  down: 1 << 1,
  left: 1 << 2,
  right: 1 << 3,
  a: 1 << 4,
  b: 1 << 5,
  start: 1 << 6,
  select: 1 << 7,
} as const
export type PadButton = keyof typeof STUDIO_PAD_MASK

/**
 * The sim polls the pad every ~30 ms and touch every ~33 ms, so a tap shorter
 * than this vanishes entirely. Every press is held for at least this long —
 * enforced by every driver, because a scripted playtest has no human finger to
 * be slow for it.
 */
export const STUDIO_MIN_PRESS_MS = 80

/** The device's logical screen; every touch coordinate is in this space. */
export const STUDIO_DEVICE_W = 320
export const STUDIO_DEVICE_H = 480

/** Combine button names into the mask the page expects. */
export function padMask(buttons: readonly string[] | undefined): number {
  let mask = 0
  for (const b of buttons ?? []) {
    mask |= STUDIO_PAD_MASK[b as PadButton] ?? 0
  }
  return mask
}

export const playtestStepSchema = z.object({
  /** Buttons held together for this step. Omit for a pure wait. */
  press: z.array(z.enum(STUDIO_PAD_BUTTONS)).max(3).optional(),
  /** How long to hold. Under 80 ms the sim's input poll never sees it. */
  hold_ms: z.number().int().min(80).max(3000).optional(),
  /** Idle time after the release (or the whole step, with no press). */
  wait_ms: z.number().int().min(0).max(5000).optional(),
  /** Capture the screen at the end of this step. */
  shot: z.boolean().optional(),
  /** What this step is for — shown to the creator and labels the frame. */
  label: z.string().max(60).optional(),
})
export type PlaytestStep = z.infer<typeof playtestStepSchema>

export const playtestInputSchema = z.object({
  /**
   * What you are trying to find out, in the creator's words: "check the frog
   * can actually land on a log". Shown under the device while it runs.
   */
  goal: z.string().min(1).max(140),
  steps: z.array(playtestStepSchema).min(1).max(24),
})
export type PlaytestInput = z.infer<typeof playtestInputSchema>

export const playtestFrameSchema = z.object({
  /** Index into `steps`. */
  i: z.number().int(),
  label: z.string().optional(),
  /** PNG of the 160x240 app canvas, base64, no data: prefix. */
  png_b64: z.string(),
})
export type PlaytestFrame = z.infer<typeof playtestFrameSchema>

/**
 * What comes back to the MAIN agent after a playtest.
 *
 * Deliberately text-only. The frames never enter this object, and therefore
 * never enter the conversation: the loop resends the whole history on every
 * step, so an image attached here would be re-sent on every subsequent turn
 * for the rest of the build — the cost growing with the square of the build's
 * length. Capping it at "the two most recent playtests" only bounds that; it
 * does not fix it.
 *
 * Instead a cheap vision sub-agent looks at the frames ONCE
 * (/api/studio/look), answers the playtest's own goal, and returns `observed`.
 * The main agent reads a sentence; the creator still sees the real pictures,
 * because the app keeps them client-side for the transcript.
 */
export const playtestOutputSchema = z.object({
  ok: z.boolean(),
  /** The device's own Lua error if it died mid-playtest. */
  error: z.string().optional(),
  where: z.string().optional(),
  /**
   * Sampled BEFORE any button is pressed. The prompt's hardest rule is that
   * something moves on the very first frame, and a sample taken across an
   * input would let a game that only moves when poked pass that check.
   */
  moves_on_its_own: z.boolean().optional(),
  steps: z
    .array(
      z.object({
        i: z.number().int(),
        label: z.string().optional(),
        buttons: z.array(z.string()).optional(),
        distinct: z.number().int(),
        nonbg: z.number().int(),
        /**
         * Whether the canvas differed across this step. On a game that
         * animates on its own this is true no matter what the button did, so
         * it is evidence of nothing — look at the frames instead. It is only
         * conclusive when moves_on_its_own is false.
         */
        screen_changed: z.boolean(),
      }),
    )
    .optional(),
  /**
   * What the vision sub-agent actually saw, in plain sentences — the answer to
   * this playtest's `goal`, plus anything visibly wrong (text off the edge, a
   * score on top of the player, something drawn behind the background).
   */
  observed: z.string().optional(),
  /** How many frames it looked at, so the model knows what `observed` covers. */
  frames_seen: z.number().int().optional(),
})
export type PlaytestOutput = z.infer<typeof playtestOutputSchema>

// ---- The vision sub-agent ---------------------------------------------------

export const lookInputSchema = z.object({
  /** The playtest's goal — the question the frames are being asked. */
  goal: z.string().min(1).max(140),
  /** What was pressed, so the observation can be tied to the actions. */
  steps: z
    .array(
      z.object({
        i: z.number().int(),
        label: z.string().optional(),
        buttons: z.array(z.string()).optional(),
      }),
    )
    .max(24)
    .optional(),
  frames: z.array(playtestFrameSchema).min(1).max(12),
  /** The draft this look belongs to, so its cost lands on the right build. */
  projectId: z.string().max(120).optional(),
})
export type LookInput = z.infer<typeof lookInputSchema>

export const lookOutputSchema = z.object({
  observed: z.string(),
  frames_seen: z.number().int(),
  /**
   * What this look cost, so the app can add it to the build's total.
   *
   * `null` means the provider did not report a cost — NOT that it was free.
   * The distinction matters: the vision sub-agent is the only part of a build
   * that sends images, so it is the line item most likely to be quietly
   * underestimated, and a silent zero here would hide exactly that.
   */
  cost_usd: z.number().nullable().optional(),
  input_tokens: z.number().int().optional(),
  output_tokens: z.number().int().optional(),
})
export type LookOutput = z.infer<typeof lookOutputSchema>

// ---- Publishing a family app ------------------------------------------------
/*
 * The parent's approve-and-install gate (docs/17-studio.md "Distribution").
 * This is the point the copilot's human-in-the-loop invariant names: nothing
 * the AI wrote reaches a kid's device without a human tap, and this is the tap.
 *
 * The request carries source files, not a package. The API is the only thing
 * that packs, so there is exactly one implementation of "what a package is"
 * and a client cannot upload bytes that skip it.
 */

/** Reserved prefix for every family-authored slug; see the CHECK constraint. */
export const FAMILY_SLUG_PREFIX = 'fam-'

export const publishAppInputSchema = z.object({
  /** The complete app, same shape write_files uses. */
  files: z.array(studioFileSchema).min(1).max(24),
  /** Shown on the launcher tile and the parent's review screen. */
  title: z.string().min(1).max(48),
  /** Who made it — "Grandma", "Sam's OT". Free text; it is a label, not an identity. */
  author: z.string().min(1).max(48),
  /** A sentence from the creator to the parent. Optional. */
  note: z.string().max(280).optional(),
  /**
   * Publish over an existing family app instead of creating one. Slugs are
   * immutable across versions — the docstore lives at /sd/docs/lib:{slug}/, so
   * a rename would orphan every savegame.
   */
  appId: z.string().uuid().optional(),
})
export type PublishAppInput = z.infer<typeof publishAppInputSchema>

export const publishAppOutputSchema = z.object({
  id: z.string().uuid(),
  slug: z.string(),
  version: z.string(),
  sha256: z.string(),
  bytes: z.number(),
})
export type PublishAppOutput = z.infer<typeof publishAppOutputSchema>

// ---- Model configuration ----------------------------------------------------
// Provider-configurable: codegen against a bespoke Lua API is a different task
// from the parent copilot's family-data Q&A, and which model wins is genuinely
// uncertain until tools/studio/eval.sh has something to say. Switchable by env
// so an A/B never touches a call site.
//
// The second provider is OpenRouter rather than OpenAI directly: one key
// reaches every model worth A/B-ing, so comparing Opus 5 against Sonnet 5 (or
// anything else) is an env change and an eval run rather than a new SDK and a
// new call site. The parent copilot is unaffected and stays pinned to OpenAI.
export type StudioAiProvider = 'anthropic' | 'openrouter'
export const STUDIO_AI_PROVIDER_DEFAULT: StudioAiProvider = 'anthropic'
export const STUDIO_MODEL_DEFAULT = 'claude-opus-5'
/**
 * The vision sub-agent's model — reads a playtest's frames (/api/studio/look).
 *
 * MUST accept image input, and that constraint is now load-bearing rather than
 * incidental: the authoring model is free to be a text-only code specialist
 * (DeepSeek v4 and the Kimi coding models both are), and this is what keeps the
 * studio able to look at its own game when it is. A text-only model here does
 * not error — it returns a confident, useless answer, which reads as "the
 * playtest saw nothing wrong".
 */
export const STUDIO_MINI_MODEL_DEFAULT = 'claude-haiku-4-5'
/**
 * OpenRouter namespaces every model by its vendor, so the IDs differ from the
 * first-party ones above even when they name the same model.
 *
 * Opus 5 is the default on both providers because it is what the eval was
 * measured on. Sonnet 5 is the obvious latency A/B — set
 * STUDIO_AI_MODEL=anthropic/claude-sonnet-5 and re-run `pnpm studio:eval` to
 * see what it costs in quality before switching for real.
 */
export const STUDIO_MODEL_DEFAULT_OPENROUTER = 'anthropic/claude-opus-5'
export const STUDIO_MINI_MODEL_DEFAULT_OPENROUTER = 'anthropic/claude-haiku-4.5'

/**
 * The models a creator may pick in the studio, and the ONLY ones the API will
 * accept from a client.
 *
 * This is one list doing two jobs on purpose. It is the picker's contents, and
 * it is the server's allowlist — a model id arriving in a request body is
 * attacker-controlled text that decides what we are billed for, so it is
 * checked against this and nothing else. Two lists would drift, and the way
 * they would drift is "the UI stopped offering the expensive one but the API
 * still accepts it".
 *
 * `blurb` is written for a parent, not a benchmark reader: what changes for
 * them is how good the game is, how long they wait, and what it costs us. The
 * per-build figures come from the ledger (apps-internal/studio-admin) where we
 * have them and are absent where we do not — an unmeasured model must not be
 * given a made-up number.
 *
 * Several of these are TEXT-ONLY (DeepSeek, GLM). That is deliberately fine:
 * the vision sub-agent that reads playtest screenshots is a separate call with
 * its own model (STUDIO_AI_VISION_MODEL), so the authoring model never needs to
 * see an image. That separation is what makes a cheap code specialist usable
 * here at all.
 */
export const STUDIO_MODELS = [
  {
    id: 'anthropic/claude-opus-5',
    name: 'Opus 5',
    blurb: 'The most careful. Best for tricky ideas, and the most expensive.',
  },
  {
    id: 'openai/gpt-5.6-sol',
    name: 'GPT-5.6 Sol',
    blurb: 'Strong all-rounder, priced like Opus.',
  },
  {
    id: 'moonshotai/kimi-k3',
    name: 'Kimi K3',
    blurb: 'Mid-priced, long memory for big games.',
  },
  {
    id: 'z-ai/glm-5.2',
    name: 'GLM 5.2',
    blurb: 'Cheap and quick. Good for small changes.',
  },
  {
    id: 'deepseek/deepseek-v4-pro',
    name: 'DeepSeek v4',
    blurb: 'Cheapest per game so far (~$0.05). Takes longer to finish.',
  },
] as const

export type StudioModelId = (typeof STUDIO_MODELS)[number]['id']

/**
 * Is this a model a client is allowed to ask for?
 *
 * Deliberately a membership test rather than a pattern: "anything starting with
 * anthropic/" would happily accept a model we have never priced, never
 * evaluated, and cannot afford.
 */
export function isStudioModel(id: unknown): id is StudioModelId {
  return typeof id === 'string' && STUDIO_MODELS.some((m) => m.id === id)
}

/** The picker's default, and what a request with no model gets. */
export const STUDIO_MODEL_PICKER_DEFAULT: StudioModelId = 'deepseek/deepseek-v4-pro'
