import { createReadStream } from 'node:fs'
import { stat } from 'node:fs/promises'
import { createServer, type Server } from 'node:http'
import { extname, join, normalize } from 'node:path'

/**
 * A localhost origin for the sim assets.
 *
 * Needed rather than file://: Emscripten fetches vupp_sim.wasm and the
 * preloaded vupp_sim.data with XHR, and a file:// page is an opaque origin that
 * cannot fetch its own siblings. Serving them is three dozen lines and removes
 * the whole class of "works for me" that comes with browser file access.
 *
 * Bound to 127.0.0.1 on an ephemeral port. This exists for the lifetime of one
 * command and is not a dev server.
 */

const TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.wasm': 'application/wasm',
  '.data': 'application/octet-stream',
  '.json': 'application/json; charset=utf-8',
}

export interface AssetServer {
  url: string
  port: number
  close(): Promise<void>
}

/**
 * Routes served from memory, ahead of the asset directory.
 *
 * `vupp play` needs a page the sim assets do not contain: studio-sim's own
 * index.html is deliberately chrome-free because React Native draws the buttons
 * around it, so a human opening it in a browser would get a screen and no way
 * to press anything. Overlaying rather than copying keeps the simulator
 * untouched — the thing being played is byte-identical to the one the phone
 * previews.
 */
export type Overlay = Record<string, { body: string | Uint8Array; type: string }>

export async function serveAssets(
  dir: string,
  overlay: Overlay = {},
  { port = 0, host = '127.0.0.1' }: { port?: number; host?: string } = {},
): Promise<AssetServer> {
  const server: Server = createServer((req, res) => {
    const raw = decodeURIComponent((req.url ?? '/').split('?')[0] ?? '/')
    const rel = normalize(raw === '/' ? '/index.html' : raw).replace(/^(\.\.[/\\])+/, '')

    const overlaid = overlay[`/${rel}`] ?? overlay[rel]
    if (overlaid) {
      const body =
        typeof overlaid.body === 'string' ? Buffer.from(overlaid.body, 'utf8') : overlaid.body
      res.writeHead(200, {
        'content-type': overlaid.type,
        'content-length': body.byteLength,
        'cache-control': 'no-store',
      })
      res.end(body)
      return
    }

    const file = join(dir, rel)

    if (!file.startsWith(dir)) {
      res.writeHead(403).end('forbidden')
      return
    }

    stat(file)
      .then((s) => {
        if (!s.isFile()) throw new Error('not a file')
        res.writeHead(200, {
          'content-type': TYPES[extname(file)] ?? 'application/octet-stream',
          'content-length': s.size,
          // The sim is single-threaded, but keeping the isolation headers on
          // costs nothing and means a future SharedArrayBuffer build does not
          // fail here in a way that looks like a bridge bug.
          'cross-origin-opener-policy': 'same-origin',
          'cross-origin-embedder-policy': 'require-corp',
          'cache-control': 'no-store',
        })
        createReadStream(file).pipe(res)
      })
      .catch(() => res.writeHead(404).end('not found'))
  })

  await new Promise<void>((ok, fail) => {
    server.once('error', fail)
    // 0.0.0.0 rather than loopback: `vupp play` is frequently run in a container
    // or over SSH, where the browser is on a different machine.
    server.listen(port, host, ok)
  })

  const address = server.address()
  if (!address || typeof address === 'string') throw new Error('asset server did not bind a port')

  return {
    port: address.port,
    url: `http://${host === '0.0.0.0' ? '127.0.0.1' : host}:${address.port}`,
    close: () =>
      new Promise<void>((ok) => {
        server.closeAllConnections?.()
        server.close(() => ok())
      }),
  }
}
