import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { join, resolve } from 'node:path'

import { type PlaytestStep, playtestInputSchema } from '@vupp/shared'

import { type Ctx, emit, progress } from '../output.js'
import { lint, lintFailure, readProject } from '../project.js'
import { resolveSimAssets } from '../sim/assets.js'
import { SimSession } from '../sim/driver.js'

/**
 * Press the buttons and look at the screen.
 *
 * This is the step that catches what neither the crash log nor the static check
 * can see: text running off the edge, the player drawn behind the background, a
 * score in a colour that vanishes against what is behind it, a button that
 * visibly does nothing.
 *
 * The frames are written to disk as PNGs and their paths returned — they are
 * NOT summarised here and there is no vision model in this path. In the parent
 * app the screenshots go to a separate sub-agent (/api/studio/look) because the
 * authoring model may be text-only and because an image on a tool result gets
 * re-sent on every later turn, so cost grows with the square of the build. An
 * AI driving this CLI has neither problem: it can open a PNG, and it decides
 * for itself what stays in its context. So it gets the actual pictures.
 *
 * `moves_on_its_own` is sampled BEFORE any button is pressed. `screen_changed`
 * is not evidence a button worked — on a game that animates by itself it is
 * true no matter what was pressed. The frames are the evidence.
 */
export interface PlaytestOptions {
  goal: string
  steps: string
  outDir?: string
}

export async function cmdPlaytest(ctx: Ctx, dir: string, opts: PlaytestOptions): Promise<number> {
  const steps = await loadSteps(opts.steps)
  const input = playtestInputSchema.parse({ goal: opts.goal, steps })

  const files = await readProject(dir)
  const checked = lint(files)
  if (!checked.ok) {
    emit(ctx, { ok: false, where: 'check', error: lintFailure(checked) }, () =>
      lintFailure(checked),
    )
    return 1
  }

  const framesDir = resolve(opts.outDir ?? join(dir, '.vupp', 'frames'))
  const assets = await resolveSimAssets({ onProgress: (m) => progress(ctx, m) })
  const sim = await SimSession.start({
    assetsDir: assets.dir,
    onProgress: (m) => progress(ctx, m),
  })

  try {
    const run = await sim.writeAndRun(files)
    if (!run.ok) {
      emit(
        ctx,
        { ok: false, where: run.where, error: run.error },
        () => `Failed (${run.where}): ${run.error}`,
      )
      return 1
    }

    progress(ctx, `playing: ${input.goal}`)
    const result = await sim.playtest(input.steps as PlaytestStep[])

    if (!result.ok) {
      emit(
        ctx,
        { ok: false, where: result.where, error: result.error },
        () => `Failed (${result.where}): ${result.error}`,
      )
      return 1
    }

    await mkdir(framesDir, { recursive: true })
    const frames: { i: number; label?: string; path: string }[] = []
    for (const frame of result.frames ?? []) {
      const name = `${String(frame.i).padStart(2, '0')}-${slug(frame.label) || 'frame'}.png`
      const path = join(framesDir, name)
      await writeFile(path, Buffer.from(frame.png_b64, 'base64'))
      frames.push({ i: frame.i, label: frame.label, path })
    }

    emit(
      ctx,
      {
        ok: true,
        goal: input.goal,
        moves_on_its_own: result.moves_on_its_own,
        steps: result.steps,
        frames,
        // Said in the output rather than left implicit: the whole point of this
        // command is that somebody looks at the pictures.
        next: frames.length
          ? 'Open every frame above and say what you actually see before deciding this passed. ' +
            'When it looks right, hand it to a person: `vupp play` is the only thing that ' +
            'answers whether a child would enjoy it.'
          : 'No frames were captured — add "shot": true to the steps where the answer would be visible.',
      },
      () => {
        const lines = [
          `Goal: ${input.goal}`,
          `Moves on its own before any input: ${result.moves_on_its_own ? 'yes' : 'NO — a still screen reads as broken to a small child'}`,
        ]
        for (const s of result.steps ?? []) {
          const pressed = s.buttons?.length ? s.buttons.join('+') : 'wait'
          lines.push(
            `  ${String(s.i).padStart(2)} ${pressed.padEnd(12)} ${s.label ?? ''}`.trimEnd() +
              `  (distinct ${s.distinct}, drawn ${s.nonbg}, changed ${s.screen_changed ? 'yes' : 'no'})`,
          )
        }
        if (frames.length) {
          lines.push('', 'Frames:')
          for (const f of frames) lines.push(`  ${f.path}${f.label ? `  ${f.label}` : ''}`)
        }
        return lines.join('\n')
      },
    )
    return 0
  } finally {
    await sim.close()
  }
}

/** Steps come as inline JSON or as a path to a JSON file — whichever is handier. */
async function loadSteps(source: string): Promise<unknown> {
  const trimmed = source.trim()
  if (trimmed.startsWith('[') || trimmed.startsWith('{')) return JSON.parse(trimmed)
  return JSON.parse(await readFile(resolve(trimmed), 'utf8'))
}

function slug(label?: string): string {
  return (label ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 32)
}
