import { type Ctx, emit, progress } from '../output.js'
import { lint, lintFailure, readProject, titleOf } from '../project.js'
import { resolveSimAssets } from '../sim/assets.js'
import { SimSession } from '../sim/driver.js'

/**
 * Put the app on a device and see whether it survives.
 *
 * Three failures, in the order they can happen, each with its own `where` so a
 * caller can tell them apart without reading prose:
 *
 *   check   vupp-lint refused it. Nothing ran.
 *   load    the engine declined to start it (bad manifest, missing main.lua).
 *   init |
 *   update |
 *   draw    the app's own Lua error, from the device, verbatim.
 *   blank   it ran and drew a single flat colour, which is the one failure the
 *           log stream cannot see and the most common thing a first build does.
 *
 * A pass can still carry warnings — a screen that never changes is legitimate
 * (a title card holds for a moment) but reads as broken to a small child, so it
 * is said out loud rather than blocked on.
 */
export async function cmdRun(ctx: Ctx, dir: string): Promise<number> {
  const files = await readProject(dir)

  const checked = lint(files)
  if (!checked.ok) {
    emit(ctx, { ok: false, where: 'check', error: lintFailure(checked) }, () =>
      lintFailure(checked),
    )
    return 1
  }

  const assets = await resolveSimAssets({ onProgress: (m) => progress(ctx, m) })
  progress(ctx, `simulator: ${assets.dir} (${assets.source})`)

  const sim = await SimSession.start({
    assetsDir: assets.dir,
    onProgress: (m) => progress(ctx, m),
  })

  try {
    const result = await sim.writeAndRun(files)
    emit(
      ctx,
      {
        ...result,
        warnings: [
          ...(checked.warnings.length ? [formatWarnings(checked)] : []),
          ...(result.warnings ?? []),
        ],
        title: result.title ?? titleOf(files),
        log: sim.log(),
        // Said in the result rather than left to be remembered: "it starts and
        // draws" is not "it is any good", and the only thing that answers the
        // second is a person holding the buttons.
        next: result.ok
          ? 'It runs. Check it with `vupp playtest`, then offer them `vupp play` so they can play it themselves.'
          : undefined,
      },
      () => {
        if (!result.ok) return `Failed (${result.where ?? 'unknown'}): ${result.error}`
        const lines = [`Running: ${result.title ?? titleOf(files)} @ ${result.fps ?? 30} fps`]
        for (const w of result.warnings ?? []) lines.push(`  warning: ${w}`)
        lines.push('', 'Play it yourself:  vupp play')
        return lines.join('\n')
      },
    )
    return result.ok ? 0 : 1
  } finally {
    await sim.close()
  }
}

function formatWarnings(checked: ReturnType<typeof lint>): string {
  return checked.warnings.map((w) => `${w.file}: ${w.message}`).join('; ')
}
