import { createHash } from 'node:crypto'
import { existsSync } from 'node:fs'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { homedir } from 'node:os'
import { dirname, join, resolve } from 'node:path'

import { APP_ENGINE_VERSION } from '@vupp/shared'

/**
 * Getting hold of a simulator without building one.
 *
 * The sim is the real firmware compiled to WASM — the same three files the
 * parent app's WebView loads (apps-internal/studio-sim). Building it needs
 * emsdk, SDL, CMake and twenty minutes, which is not something to ask of
 * someone who wanted to make a game for their kid. So we fetch it.
 *
 * Resolution order, most specific first:
 *   1. VUPP_SIM_DIR      — an explicit directory of assets.
 *   2. a repo checkout   — apps-internal/studio-sim/public, walking up from
 *                          cwd. Keeps the in-repo dev loop instant and means a
 *                          firmware change is picked up by `pnpm studio-sim:build`
 *                          alone, with nothing to re-publish or re-download.
 *   3. VUPP_SIM_URL      — a base URL to download and cache from.
 *   4. DEFAULT_SIM_URL   — the published release, so a fresh container works
 *                          with no configuration at all.
 */

/** The files the page needs. index.html and bridge.js are committed; the rest are built. */
export const SIM_FILES = [
  'index.html',
  'bridge.js',
  'vupp_sim.js',
  'vupp_sim.wasm',
  'vupp_sim.data',
] as const

export const SIM_MANIFEST = 'manifest.json'

/**
 * Where a machine with no configuration gets its simulator.
 *
 * A GitHub release asset, and the tag carries the engine version — so this
 * constant does not need editing when the engine moves, and an old CLI keeps
 * pointing at the sim it was built to speak to rather than silently upgrading
 * underneath itself. The bridge contract changes between engine versions; a CLI
 * that fetched "latest" would eventually playtest firmware it cannot drive.
 *
 * Release assets live at <base>/<filename>, which is exactly the layout
 * downloadSimAssets already fetches, so nothing here is GitHub-specific beyond
 * the string. Every file is still checked against the manifest's sha256 before
 * it is run.
 */
export const SIM_RELEASE_BASE = 'https://github.com/nicholasareed/vupp-sdk/releases/download'

export function defaultSimUrl(engine: number): string {
  return `${SIM_RELEASE_BASE}/sim-engine${engine}`
}

export interface SimManifest {
  /** APP_ENGINE_VERSION the sim was built from. */
  engine: number
  files: { name: string; sha256: string; bytes: number }[]
}

export interface SimAssets {
  dir: string
  source: 'dir' | 'repo' | 'cache'
  /** Present when the assets came with one; local builds have none. */
  manifest: SimManifest | null
}

export class SimAssetError extends Error {}

const CACHE_ROOT = join(process.env.VUPP_CACHE_DIR ?? join(homedir(), '.cache', 'vupp'), 'sim')

/** Walk up from `from` looking for a repo checkout with built sim assets. */
export function findRepoAssets(from = process.cwd()): string | null {
  let dir = resolve(from)
  for (;;) {
    const candidate = join(dir, 'apps-internal', 'studio-sim', 'public')
    if (existsSync(join(candidate, 'vupp_sim.wasm'))) return candidate
    const parent = dirname(dir)
    if (parent === dir) return null
    dir = parent
  }
}

async function readManifest(dir: string): Promise<SimManifest | null> {
  try {
    return JSON.parse(await readFile(join(dir, SIM_MANIFEST), 'utf8')) as SimManifest
  } catch {
    return null
  }
}

function missingFrom(dir: string): string[] {
  return SIM_FILES.filter((f) => !existsSync(join(dir, f)))
}

export interface ResolveOptions {
  /** Never reach the network; fail instead. */
  offline?: boolean
  /** Re-download even when the cache looks complete. */
  refresh?: boolean
  /** Progress, for `vupp doctor`. */
  onProgress?: (message: string) => void
}

export async function resolveSimAssets(opts: ResolveOptions = {}): Promise<SimAssets> {
  const explicit = process.env.VUPP_SIM_DIR
  if (explicit) {
    const dir = resolve(explicit)
    const missing = missingFrom(dir)
    if (missing.length) {
      throw new SimAssetError(
        `VUPP_SIM_DIR is set to ${dir} but ${missing.join(', ')} ${missing.length === 1 ? 'is' : 'are'} missing there.`,
      )
    }
    return { dir, source: 'dir', manifest: await readManifest(dir) }
  }

  const repo = findRepoAssets()
  if (repo && missingFrom(repo).length === 0) {
    return { dir: repo, source: 'repo', manifest: await readManifest(repo) }
  }

  const url = process.env.VUPP_SIM_URL ?? defaultSimUrl(APP_ENGINE_VERSION)
  try {
    return await downloadSimAssets(url, opts)
  } catch (err) {
    if (process.env.VUPP_SIM_URL) throw err
    // The default is a published release, so a failure here is usually offline
    // or a proxy rather than a wrong URL — say what to do about both, and name
    // the URL that was tried so it is not a mystery.
    throw new SimAssetError(
      `Could not fetch the simulator from ${url}\n` +
        `  ${err instanceof Error ? err.message : String(err)}\n\n` +
        '  If you are offline or behind a proxy, set VUPP_SIM_DIR to a directory\n' +
        '  holding the studio-sim assets, or VUPP_SIM_URL to somewhere reachable.',
    )
  }
}

/**
 * Fetch the assets into a content-addressed cache directory.
 *
 * Keyed by the manifest's own hash rather than by engine version: two builds of
 * engine 9 are not interchangeable (the bridge contract moves between them), and
 * a cache that answers "close enough" would produce a playtest of firmware the
 * child will never run.
 */
export async function downloadSimAssets(
  base: string,
  opts: ResolveOptions = {},
): Promise<SimAssets> {
  if (opts.offline) throw new SimAssetError('--offline was given, but nothing is cached yet.')
  const origin = base.replace(/\/+$/, '')
  const progress = opts.onProgress ?? (() => {})

  progress(`fetching ${SIM_MANIFEST} from ${origin}`)
  const manifest = await fetchJson<SimManifest>(`${origin}/${SIM_MANIFEST}`)
  const key = createHash('sha256').update(JSON.stringify(manifest)).digest('hex').slice(0, 16)
  const dir = join(CACHE_ROOT, `engine${manifest.engine}-${key}`)

  if (!opts.refresh && missingFrom(dir).length === 0) {
    progress(`cached at ${dir}`)
    return { dir, source: 'cache', manifest }
  }

  await mkdir(dir, { recursive: true })
  for (const entry of manifest.files) {
    progress(`downloading ${entry.name} (${Math.round(entry.bytes / 1024)} KB)`)
    const res = await fetch(`${origin}/${entry.name}`)
    if (!res.ok) {
      throw new SimAssetError(`${origin}/${entry.name} answered ${res.status} ${res.statusText}`)
    }
    const bytes = new Uint8Array(await res.arrayBuffer())
    const got = createHash('sha256').update(bytes).digest('hex')
    if (got !== entry.sha256) {
      throw new SimAssetError(
        `${entry.name} does not match the manifest (expected ${entry.sha256.slice(0, 12)}…, got ${got.slice(0, 12)}…). ` +
          'Refusing to run firmware that arrived corrupted or modified.',
      )
    }
    await writeFile(join(dir, entry.name), bytes)
  }
  await writeFile(join(dir, SIM_MANIFEST), `${JSON.stringify(manifest, null, 2)}\n`)

  const missing = missingFrom(dir)
  if (missing.length) {
    throw new SimAssetError(`the manifest at ${origin} does not list ${missing.join(', ')}`)
  }
  return { dir, source: 'cache', manifest }
}

async function fetchJson<T>(url: string): Promise<T> {
  const res = await fetch(url)
  if (!res.ok) throw new SimAssetError(`${url} answered ${res.status} ${res.statusText}`)
  try {
    return (await res.json()) as T
  } catch {
    throw new SimAssetError(`${url} did not return JSON — is that the right base URL?`)
  }
}
